function applyCss(root) { (root || document).querySelectorAll('[data-css]').forEach(n => { n.style.cssText = n.getAttribute('data-css'); n.removeAttribute('data-css'); }); }
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const mean = a => { let s = 0, n = 0; for (const v of a) if (v != null && !Number.isNaN(v)) { s += v; n++; } return n ? s / n : null; };
const toIndex = m => (m == null ? null : (m - 1) / 3 * 100);
const fmt = (v, d = 0) => (v == null ? '–' : (Math.round(v * 10 ** d) / 10 ** d).toFixed(d));
const pct = (a, b) => (b ? Math.round(100 * a / b) : 0);
const bandOf = idx => { if (idx == null) return null; let b = CONFIG.bands[0]; for (const x of CONFIG.bands) if (idx >= x.min) b = x; return b; };
const isAnalyst = () => S.view === 'analyst';

/* ---------------------------------- CSV parsing ---------------------------------- */
/* MAP-START (pure functions; also exercised by tools/test_column_mapping.js) */
function detectDelimiter(text) {
  // Count delimiters outside quotes in the first few lines; Excel re-saves may use ; or tab.
  const head = text.slice(0, 20000);
  const counts = { ',': 0, ';': 0, '\t': 0 }; let q = false, lines = 0;
  for (const c of head) {
    if (c === '"') q = !q;
    else if (!q && c in counts) counts[c]++;
    else if (!q && c === '\n' && ++lines >= 5) break;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0][1] > 0 ? Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0] : ',';
}
function parseCSV(text, delim) {
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  delim = delim || detectDelimiter(text);
  const rows = []; let row = [], f = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; }
      else f += c;
    } else if (c === '"') q = true;
    else if (c === delim) { row.push(f); f = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(f); f = ''; if (row.some(x => x !== '')) rows.push(row); row = [];
    } else f += c;
  }
  row.push(f); if (row.some(x => x !== '')) rows.push(row);
  return rows;
}

function parseAnswer(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return undefined;                       // left blank
  const m = s.match(/^([1-4])(?:\s*[-–—:.)]|\s*$)/);
  if (m) return +m[1];
  if (/outside my area|would not know/i.test(s)) return null;   // "Outside my area": excluded from scores
  return 'bad';
}

/* Find the header row and map columns. Question columns are matched three ways, in order:
   1) a "Q1"…"Q12" prefix, 2) the practice name (e.g. "Named data owner"),
   3) content: leftover columns whose answers look like the 1–4 scale, taken left to right. */
function mapColumns(rows) {
  let best = null;
  for (let h = 0; h < Math.min(10, rows.length); h++) {
    const header = rows[h].map(x => String(x == null ? '' : x).replace(/ /g, ' ').replace(/\s+/g, ' ').trim());
    const col = {}, qcol = {}, how = {};
    for (const [k, re] of Object.entries(CONFIG.columns)) { const i = header.findIndex(t => re.test(t)); if (i >= 0) col[k] = i; }
    const taken = i => Object.values(qcol).includes(i);
    header.forEach((t, i) => { const m = t.match(/^Q\s*(\d{1,2})\b/i); if (m && +m[1] >= 1 && +m[1] <= 12 && qcol[+m[1]] == null) { qcol[+m[1]] = i; how[+m[1]] = 'Q number'; } });
    ITEMS.forEach(n => {
      if (qcol[n] != null) return;
      const s = CONFIG.items[n].short.toLowerCase();
      const i = header.findIndex((t, i) => !taken(i) && t.toLowerCase().includes(s));
      if (i >= 0) { qcol[n] = i; how[n] = 'practice name'; }
    });
    const score = Object.keys(col).length + Object.keys(qcol).length;
    if (!best || score > best.score) best = { headerRow: h, header, col, qcol, how, score };
  }
  const missing = ITEMS.filter(n => best.qcol[n] == null);
  if (missing.length) {
    const used = new Set([...Object.values(best.col), ...Object.values(best.qcol)]);
    const data = rows.slice(best.headerRow + 1);
    const cands = best.header.map((_, i) => i).filter(i => !used.has(i)).filter(i => {
      let ok = 0, tot = 0;
      data.forEach(r => { const a = parseAnswer(r[i]); if (a !== undefined) { tot++; if (a !== 'bad') ok++; } });
      return tot > 0 && ok / tot >= 0.9;
    });
    if (cands.length === missing.length) missing.forEach((n, j) => { best.qcol[n] = cands[j]; best.how[n] = 'answers (position)'; });
    else best.note = `${cands.length} unmatched column(s) contain 1–4 answers, but ${missing.length} question(s) are missing, so they could not be assigned safely.`;
  }
  return best;
}
/* MAP-END */
function parseTs(s) {
  if (!s) return null;
  const m = String(s).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) return new Date(+m[3], +m[1] - 1, +m[2], +m[4], +m[5], +(m[6] || 0));
  const d = new Date(s); return isNaN(d) ? null : d;
}
const cycleOf = d => { if (!d) return 'Undated'; const y = d.getFullYear(); return d.getMonth() >= 6 ? `${y}–${String(y + 1).slice(2)}` : `${y - 1}–${String(y).slice(2)}`; };
function normOption(dim, v) {
  const s = String(v || '').trim();
  if (!s) return 'Not reported';
  const opts = CONFIG.options[dim];
  if (!opts) return s;
  const hit = opts.find(o => o.toLowerCase() === s.toLowerCase());
  return hit || 'Other';
}
function normName(s) {
  return String(s || '').toLowerCase().replace(/&/g, 'and')
    .replace(/\b(public|community|area|consolidated|school|schools|district|the)\b/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ').trim();
}

/* ---------------------------------- Ingest ---------------------------------- */
function ingest(text, fileName) {
  const delim = detectDelimiter(text);
  const rows = parseCSV(text, delim);
  if (rows.length < 2) { alert('That file has no response rows.'); return; }
  const map = mapColumns(rows);
  const { col, qcol } = map;
  const missing = [];
  ITEMS.forEach(q => { if (qcol[q] == null) missing.push('Q' + q); });
  ['eem', 'dname', 'region', 'enroll', 'locale', 'role'].forEach(k => { if (col[k] == null) missing.push(k); });
  const get = (r, k) => (col[k] == null ? '' : (r[col[k]] || '').trim());
  const q = { rowsRead: rows.length - 1 - map.headerRow, missingCols: missing, notFound: [], badAnswers: 0, blankAnswers: 0, dupes: 0, profileConflicts: [], freeTextCount: 0, noDistrict: 0,
    map, delim: delim === '\t' ? 'tab' : delim, qMissing: missing.filter(m => m[0] === 'Q') };

  let recs = [];
  for (let i = map.headerRow + 1; i < rows.length; i++) {
    const r = rows[i];
    const rawCode = get(r, 'eem');
    const dname = get(r, 'dname');
    const digits = rawCode.replace(/\D/g, '');
    let dk, code = '';
    if (digits.length >= 3 && !/not\s*found/i.test(rawCode)) { code = digits.padStart(5, '0'); dk = 'EEM:' + code; }
    else if (dname) { dk = 'NAME:' + normName(dname); q.notFound.push({ code: rawCode || '(blank)', name: dname }); }
    else { q.noDistrict++; continue; }
    const answers = {};
    ITEMS.forEach(n => {
      const a = parseAnswer(qcol[n] == null ? '' : r[qcol[n]]);
      if (a === 'bad') { q.badAnswers++; answers[n] = undefined; }
      else { if (a === undefined) q.blankAnswers++; answers[n] = a; }
    });
    if (get(r, 'freetext')) q.freeTextCount++;
    recs.push({
      ts: parseTs(get(r, 'ts')), dk, code, dname,
      _email: get(r, 'email').toLowerCase(),        // used only for de-duplication, then deleted
      role: normOption('role', get(r, 'role')), scope: normOption('scope', get(r, 'scope')),
      region: get(r, 'region') || 'Not reported', enroll: normOption('enroll', get(r, 'enroll')),
      locale: normOption('locale', get(r, 'locale')), policy: normOption('policy', get(r, 'policy')),
      staff: normOption('staff', get(r, 'staff')), barrier: normOption('barrier', get(r, 'barrier')),
      followup: get(r, 'followup'), answers,
    });
    // Respondent name and free-text comments are deliberately never read into memory.
  }
  // De-duplicate: same email + same district → keep the latest submission.
  const latest = new Map();
  for (const r of recs) {
    if (!r._email) continue;
    const k = r._email + '|' + r.dk;
    const prev = latest.get(k);
    if (!prev || (r.ts && prev.ts && r.ts > prev.ts)) latest.set(k, r);
  }
  const before = recs.length;
  recs = recs.filter(r => !r._email || latest.get(r._email + '|' + r.dk) === r);
  q.dupes = before - recs.length;
  recs.forEach(r => { delete r._email; r.cycle = cycleOf(r.ts); });

  S.all = recs; S.quality = q; S.fileName = fileName; S.loadedAt = new Date();
  const cycles = [...new Set(recs.map(r => r.cycle))].sort();
  S.cycle = cycles.length ? cycles[cycles.length - 1] : 'all';
  S.report.target = '';
  render();
}

/* ---------------------------------- Model ---------------------------------- */
function respIndex(r) { return toIndex(mean(ITEMS.map(n => r.answers[n]))); }
function respDomain(r, d) { return toIndex(mean(d.items.map(n => r.answers[n]))); }
function modeOf(vals) {
  const c = new Map(); vals.forEach(v => { if (v && v !== 'Not reported') c.set(v, (c.get(v) || 0) + 1); });
  let best = 'Not reported', n = 0; for (const [k, v] of c) if (v > n) { best = k; n = v; }
  return { value: best, conflict: c.size > 1 };
}

function buildModel() {
  const recs = S.cycle === 'all' ? S.all : S.all.filter(r => r.cycle === S.cycle);
  const by = new Map();
  recs.forEach(r => { if (!by.has(r.dk)) by.set(r.dk, []); by.get(r.dk).push(r); });
  const conflicts = [];
  const districts = [...by.entries()].map(([dk, rs]) => {
    rs.sort((a, b) => (b.ts || 0) - (a.ts || 0));
    const itemMeans = {}, spread = {}, outside = {}, dist = {};
    ITEMS.forEach(n => {
      const v = rs.map(r => r.answers[n]).filter(x => typeof x === 'number');
      itemMeans[n] = v.length ? mean(v) : null;
      spread[n] = v.length >= 2 ? Math.max(...v) - Math.min(...v) : 0;
      outside[n] = rs.filter(r => r.answers[n] === null).length;
      dist[n] = { 1: 0, 2: 0, 3: 0, 4: 0, 0: 0 };
      rs.forEach(r => { const a = r.answers[n]; if (a === null) dist[n][0]++; else if (typeof a === 'number') dist[n][a]++; });
    });
    const domains = {};
    CONFIG.domains.forEach(d => { domains[d.id] = toIndex(mean(d.items.map(n => itemMeans[n]))); });
    const profile = {};
    ['region', 'enroll', 'locale', 'policy', 'staff'].forEach(k => {
      const m = modeOf(rs.map(r => r[k])); profile[k] = m.value; if (m.conflict) conflicts.push({ dk, field: k });
    });
    const nm = modeOf(rs.map(r => r.dname)).value;
    return {
      dk, code: rs.find(r => r.code)?.code || '', label: nm === 'Not reported' ? dk : nm,
      n: rs.length, recs: rs, itemMeans, spread, outside, dist, domains,
      index: toIndex(mean(ITEMS.map(n => itemMeans[n]))), profile,
      barriers: rs.map(r => r.barrier).filter(b => b !== 'Not reported'),
      scopes: rs.map(r => r.scope),
    };
  }).sort((a, b) => a.label.localeCompare(b.label));
  return { recs, districts, conflicts };
}

/* Aggregate a set of districts (statewide or region). Each district counts once in scores. */
function aggregate(districts, recs) {
  const scored = districts.filter(d => d.index != null);
  const agg = {
    nDistricts: districts.length, nResp: recs.length,
    index: mean(scored.map(d => d.index)),
    domains: {}, itemMeans: {}, dist: {}, outsideRate: {}, bands: {}, barriers: {}, disagree: {},
    multi: districts.filter(d => d.n >= 2),
  };
  CONFIG.domains.forEach(d => { agg.domains[d.id] = mean(districts.map(x => x.domains[d.id])); });
  ITEMS.forEach(n => {
    agg.itemMeans[n] = mean(districts.map(d => d.itemMeans[n]));
    const c = { 1: 0, 2: 0, 3: 0, 4: 0, 0: 0 };
    recs.forEach(r => { const a = r.answers[n]; if (a === null) c[0]++; else if (typeof a === 'number') c[a]++; });
    agg.dist[n] = c;
    const tot = c[0] + c[1] + c[2] + c[3] + c[4];
    agg.outsideRate[n] = tot ? c[0] / tot : 0;
    agg.disagree[n] = agg.multi.filter(d => d.spread[n] >= S.settings.gap).length;
  });
  CONFIG.bands.forEach(b => (agg.bands[b.name] = 0));
  scored.forEach(d => agg.bands[bandOf(d.index).name]++);
  recs.forEach(r => { if (r.barrier !== 'Not reported') agg.barriers[r.barrier] = (agg.barriers[r.barrier] || 0) + 1; });
  return agg;
}

/* Breakdown with small-cell suppression. Groups with fewer than k districts are pooled
   into "Other (combined)". If the pool is still below k, the next-smallest published
   group is folded in too, so no hidden group can be recovered by subtraction. */
function breakdown(model, dimId) {
  const dim = CONFIG.dims.find(d => d.id === dimId);
  const k = S.settings.minCell;
  const g = new Map();
  const add = (label, dk, idx, doms) => {
    if (!g.has(label)) g.set(label, { label, dks: new Set(), idx: [], doms: Object.fromEntries(CONFIG.domains.map(d => [d.id, []])), units: 0 });
    const x = g.get(label); x.dks.add(dk); x.idx.push(idx); x.units++;
    CONFIG.domains.forEach(d => x.doms[d.id].push(doms[d.id]));
  };
  if (dim.level === 'district') model.districts.forEach(d => add(d.profile[dimId] || 'Not reported', d.dk, d.index, d.domains));
  else model.recs.forEach(r => add(r[dimId] || 'Not reported', r.dk, respIndex(r), Object.fromEntries(CONFIG.domains.map(d => [d.id, respDomain(r, d)]))));

  const order = CONFIG.options[dimId] || null;
  let groups = [...g.values()];
  const keep = groups.filter(x => x.dks.size >= k).sort((a, b) => a.dks.size - b.dks.size);
  const small = groups.filter(x => x.dks.size < k);
  let pool = null;
  if (small.length) {
    pool = { label: 'Other (combined)', members: small.map(x => x.label), dks: new Set(), idx: [], doms: Object.fromEntries(CONFIG.domains.map(d => [d.id, []])), units: 0 };
    const absorb = x => { x.dks.forEach(v => pool.dks.add(v)); pool.idx.push(...x.idx); pool.units += x.units; CONFIG.domains.forEach(d => pool.doms[d.id].push(...x.doms[d.id])); };
    small.forEach(absorb);
    while (pool.dks.size < k && keep.length) { const x = keep.shift(); pool.members.push(x.label); absorb(x); }
    pool.suppressed = pool.dks.size < k;
  }
  const sortFn = (a, b) => order ? (order.indexOf(a.label) - order.indexOf(b.label)) || a.label.localeCompare(b.label) : b.dks.size - a.dks.size || a.label.localeCompare(b.label);
  const out = keep.sort(sortFn).map(x => ({ label: x.label, n: x.dks.size, units: x.units, index: mean(x.idx), doms: Object.fromEntries(CONFIG.domains.map(d => [d.id, mean(x.doms[d.id])])) }));
  if (pool) out.push({ label: pool.label, members: pool.members, n: pool.dks.size, units: pool.units, suppressed: pool.suppressed, pooled: true, index: pool.suppressed ? null : mean(pool.idx), doms: Object.fromEntries(CONFIG.domains.map(d => [d.id, pool.suppressed ? null : mean(pool.doms[d.id])])) });
  return { dim, rows: out };
}

/* Next steps: lowest-scoring answered items first; ties go to the foundation (Leadership) first. */
function nextSteps(itemMeans, count = 3) {
  return ITEMS.filter(n => itemMeans[n] != null && itemMeans[n] < 4)
    .sort((a, b) => (itemMeans[a] - itemMeans[b]) || (a - b))
    .slice(0, count);
}

/* ---------------------------------- Chart pieces ---------------------------------- */
function domainChart(domains, opts = {}) {
  // Rendered top-down as the building: Data Use on top, Leadership as the foundation.
  const list = CONFIG.domains.slice().reverse();
  const W = 640, L = 170, R = 46, rowH = 40, top = 22, H = top + list.length * rowH + 8;
  const x = v => L + (W - L - R) * v / 100;
  const alt = 'Domain scores out of 100: ' + list.map(d => `${d.name} ${fmt(domains[d.id])}` + (opts.bench && opts.bench[d.id] != null ? ` (statewide ${fmt(opts.bench[d.id])})` : '')).join('; ') + '.';
  let s = `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${esc(alt)}">`;
  [0, 25, 50, 75, 100].forEach(t => {
    s += `<line x1="${x(t)}" x2="${x(t)}" y1="${top - 4}" y2="${H - 6}" stroke="${t === 0 ? 'var(--axis)' : 'var(--grid)'}" stroke-width="1"/>`;
    s += `<text x="${x(t)}" y="${top - 9}" font-size="11" fill="var(--muted)" text-anchor="middle">${t}</text>`;
  });
  list.forEach((d, i) => {
    const y = top + i * rowH + 8, v = domains[d.id], bh = 18;
    s += `<text x="0" y="${y + 9}" font-size="13" fill="var(--ink)">${esc(d.name)}</text>`;
    s += `<text x="0" y="${y + 24}" font-size="11" fill="var(--muted)">${esc(d.metaphor)}</text>`;
    if (v != null) {
      const w = Math.max(2, x(v) - L);
      s += `<path d="M${L},${y} h${Math.max(0, w - 4)} a4,4 0 0 1 4,4 v${bh - 8} a4,4 0 0 1 -4,4 h-${Math.max(0, w - 4)} z" fill="var(--bar)" data-tip="${esc(d.name)}: ${fmt(v)} / 100 · ${esc(bandOf(v).name)}"/>`;
      s += `<text x="${x(v) + 6}" y="${y + 13}" font-size="13" font-weight="650" fill="var(--ink)">${fmt(v)}</text>`;
    } else s += `<text x="${L + 4}" y="${y + 13}" font-size="12" fill="var(--muted)">Not scored</text>`;
    if (opts.bench && opts.bench[d.id] != null) {
      const bx = x(opts.bench[d.id]);
      s += `<line x1="${bx}" x2="${bx}" y1="${y - 4}" y2="${y + bh + 4}" stroke="var(--ink)" stroke-width="2" data-tip="Statewide average: ${fmt(opts.bench[d.id])}"/>`;
    }
  });
  s += '</svg>';
  if (opts.bench) s += `<div class="legend"><span><i data-css="background:var(--bar)"></i>${esc(opts.selfLabel || 'This group')}</span><span><i data-css="background:var(--ink);width:3px"></i>Statewide average</span></div>`;
  return s;
}

function scaleLegend() {
  return `<div class="legend">${[1, 2, 3, 4, 0].map(k => `<span><i data-css="background:${SCALE_COLORS[k]}"></i>${SCALE_LABELS[k]}</span>`).join('')}</div>`;
}
function stackBar(c, unit) {
  const tot = c[0] + c[1] + c[2] + c[3] + c[4];
  if (!tot) return '<div class="stack"><span class="supp" data-css="flex:1">No answers</span></div>';
  const alt = [1, 2, 3, 4, 0].filter(k => c[k]).map(k => `${SCALE_LABELS[k]}: ${c[k]} (${Math.round(100 * c[k] / tot)}%)`).join('; ');
  return `<div class="stack" role="img" aria-label="${esc(alt)}">${[1, 2, 3, 4, 0].filter(k => c[k]).map(k => {
    const p = 100 * c[k] / tot;
    return `<span data-css="flex:${c[k]} 1 0;background:${SCALE_COLORS[k]};color:${SCALE_TEXT[k]}" data-tip="${SCALE_LABELS[k]}: ${c[k]} ${unit}${c[k] === 1 ? '' : 's'} (${Math.round(p)}%)">${p >= 9 ? Math.round(p) + '%' : ''}</span>`;
  }).join('')}</div>`;
}
function questionChart(agg, unit = 'response', bench = null) {
  const rc = bench ? 'qrow b' : 'qrow';
  let s = scaleLegend() + `<div class="${rc} head"><div>Question</div><div>Share of ${unit}s</div><div class="num">Mean</div>${bench ? '<div class="num">State</div>' : ''}<div class="num">Outside</div></div>`;
  CONFIG.domains.forEach(d => {
    s += `<div class="domhead">${esc(d.name)}</div>`;
    d.items.forEach(n => {
      s += `<div class="${rc}"><div class="ql">Q${n}. ${esc(CONFIG.items[n].short)}</div>${stackBar(agg.dist[n], unit)}<div class="num" data-tip="Mean of 1–4 answers, district-weighted">${fmt(agg.itemMeans[n], 2)}</div>${bench ? `<div class="num" data-tip="Statewide mean, district-weighted">${fmt(bench[n], 2)}</div>` : ''}<div class="num" data-tip="Share who answered 'Outside my area'">${Math.round(100 * agg.outsideRate[n])}%</div></div>`;
    });
  });
  s += `<details class="tableview"><summary>Show as table</summary><div class="tablewrap"><table class="data"><thead><tr><th>Question</th>${[1, 2, 3, 4, 0].map(k => `<th class="n">${SCALE_LABELS[k]}</th>`).join('')}<th class="n">Mean</th>${bench ? '<th class="n">Statewide</th>' : ''}</tr></thead><tbody>${ITEMS.map(n => `<tr><td>Q${n}. ${esc(CONFIG.items[n].short)}</td>${[1, 2, 3, 4, 0].map(k => `<td class="n">${agg.dist[n][k]}</td>`).join('')}<td class="n">${fmt(agg.itemMeans[n], 2)}</td>${bench ? `<td class="n">${fmt(bench[n], 2)}</td>` : ''}</tr>`).join('')}</tbody></table></div></details>`;
  return s;
}
function hbars(rows, opts = {}) {
  // rows: [{label, value, tip}] — single series, so no legend box
  const max = opts.max || Math.max(1, ...rows.map(r => r.value || 0));
  return `<table class="data"><tbody>${rows.map(r => `<tr><td data-css="width:46%">${esc(r.label)}</td><td aria-hidden="true"><span class="minitrack" data-css="width:60%"><span class="mini" data-css="width:${100 * (r.value || 0) / max}%" data-tip="${esc(r.tip || '')}"></span></span></td><td class="n" data-css="width:64px">${esc(r.text != null ? r.text : r.value)}</td></tr>`).join('')}</tbody></table>`;
}
function bandsChart(agg) {
  const tot = Object.values(agg.bands).reduce((a, b) => a + b, 0);
  return hbars(CONFIG.bands.map((b, i) => ({
    label: `${b.min}–${i < 3 ? CONFIG.bands[i + 1].min - 1 : 100}  ${b.name}`,
    value: agg.bands[b.name], text: `${agg.bands[b.name]} (${pct(agg.bands[b.name], tot)}%)`,
    tip: `${b.name}: ${b.hint}`,
  })), { max: tot });
}
function barrierChart(agg) {
  const tot = Object.values(agg.barriers).reduce((a, b) => a + b, 0);
  const rows = CONFIG.options.barrier.filter(b => agg.barriers[b]).map(b => ({ label: b, value: agg.barriers[b], text: `${pct(agg.barriers[b], tot)}%`, tip: `${agg.barriers[b]} responses` }));
  rows.sort((a, b) => b.value - a.value);
  return rows.length ? hbars(rows, { max: tot }) : '<p class="supp">No answers yet.</p>';
}
function stepsList(ns, means) {
  if (!ns.length) return '<p class="fine">No gaps: every answered item averaged a 4.</p>';
  return `<ol class="steps">${ns.map(n => `<li><div class="t">${esc(CONFIG.items[n].short)} <span class="pill">${esc(domainOf(n).name)} · avg ${fmt(means[n], 1)}</span></div><div>${esc(CONFIG.items[n].action)}</div><div class="cite">${esc(CONFIG.items[n].cite)}</div></li>`).join('')}</ol>`;
}

/* Share of a group's multi-respondent districts whose answers to each question were gap+ points apart.
   Suppressed until at least k districts in the group have more than one respondent. */
function disagreeBars(agg, k, where) {
  const multiN = agg.multi.length;
  if (multiN < k) return `<p class="fine">Shown once at least ${k} districts ${where} have more than one respondent (currently ${multiN}).</p>`;
  return `<p class="sub fine">Of the ${multiN} districts ${where} with more than one respondent, the share where answers to a question were ${S.settings.gap}+ points apart. "Where you disagree is the finding."</p>${hbars(ITEMS.map(n => ({ label: `Q${n}. ${CONFIG.items[n].short}`, value: agg.disagree[n], text: `${pct(agg.disagree[n], multiN)}%`, tip: `${agg.disagree[n]} of ${multiN} multi-respondent districts` })), { max: multiN })}`;
}

/* One district's spread of answers per question: a line from the lowest to the highest answer,
   a dot for each answer given (larger = more people), and a tick at the district mean. */
function rangeChart(d) {
  const gap = S.settings.gap;
  const W = 680, L = 250, R = 92, rowH = 26, top = 26;
  const rows = [];
  CONFIG.domains.forEach(dm => { rows.push({ head: dm.name }); dm.items.forEach(n => rows.push({ n })); });
  const H = top + rows.length * rowH + 4;
  const x = v => L + (W - L - R) * (v - 1) / 3;
  const apart = ITEMS.filter(n => { const v = [1, 2, 3, 4].filter(k => d.dist[n][k]); return v.length >= 2 && Math.max(...v) - Math.min(...v) >= gap; });
  const alt = `Range of answers by practice, 1 to 4. ${apart.length ? `Answers were ${gap} or more points apart on ${apart.map(n => 'Q' + n).join(', ')}.` : 'No practice had answers ' + gap + ' or more points apart.'} The same answers are listed in the table.`;
  let s = `<svg viewBox="0 0 ${W} ${H}" width="100%" data-css="max-width:${W}px" role="img" aria-label="${esc(alt)}">`;
  [1, 2, 3, 4].forEach(t => {
    s += `<line x1="${x(t)}" x2="${x(t)}" y1="${top - 6}" y2="${H - 2}" stroke="var(--grid)" stroke-width="1"/>`;
    s += `<text x="${x(t)}" y="${top - 11}" font-size="11" fill="var(--muted)" text-anchor="middle">${t}</text>`;
  });
  s += `<text x="${W - R + 22}" y="${top - 11}" font-size="11" fill="var(--muted)">Spread</text>`;
  rows.forEach((r, i) => {
    const y = top + i * rowH + rowH / 2;
    if (r.head) { s += `<text x="0" y="${y + 6}" font-size="11" font-weight="650" fill="var(--muted)" letter-spacing=".04em">${esc(r.head.toUpperCase())}</text>`; return; }
    const n = r.n, c = d.dist[n];
    const vals = [1, 2, 3, 4].filter(k => c[k]);
    const sp = vals.length ? Math.max(...vals) - Math.min(...vals) : 0;
    const flag = vals.length >= 2 && sp >= gap;
    if (flag) s += `<rect x="0" y="${y - rowH / 2 + 1}" width="${W}" height="${rowH - 2}" rx="4" fill="#fdf0ef"/>`;
    const lbl = `Q${n}. ${CONFIG.items[n].short}`;
    s += `<text x="0" y="${y + 4}" font-size="12" fill="var(--ink)">${esc(lbl.length > 38 ? lbl.slice(0, 37) + '…' : lbl)}<title>${esc(lbl)}</title></text>`;
    if (!vals.length) s += `<text x="${L}" y="${y + 4}" font-size="11" fill="var(--muted)">No 1–4 answers</text>`;
    else {
      if (vals.length > 1) s += `<line x1="${x(Math.min(...vals))}" x2="${x(Math.max(...vals))}" y1="${y}" y2="${y}" stroke="var(--ink-2)" stroke-width="2" stroke-linecap="round"/>`;
      vals.forEach(k => { const rr = Math.min(11, 5 + 1.5 * (c[k] - 1)); s += `<circle cx="${x(k)}" cy="${y}" r="${rr}" fill="${SCALE_COLORS[k]}" stroke="var(--card)" stroke-width="2" data-tip="${c[k]} answered ${esc(SCALE_LABELS[k])}"/>`; });
      if (d.itemMeans[n] != null) s += `<line x1="${x(d.itemMeans[n])}" x2="${x(d.itemMeans[n])}" y1="${y - 9}" y2="${y + 9}" stroke="var(--ink)" stroke-width="2" data-tip="District mean ${fmt(d.itemMeans[n], 2)}"/>`;
    }
    s += `<text x="${W - R + 22}" y="${y + 4}" font-size="12" fill="var(--ink)" font-weight="${flag ? 650 : 400}">${vals.length >= 2 ? sp : '–'}</text>`;
    if (c[0]) s += `<text x="${W - 4}" y="${y + 4}" font-size="11" fill="var(--muted)" text-anchor="end" data-tip="${c[0]} said 'Outside my area'">+${c[0]} out</text>`;
  });
  s += '</svg>';
  return `<div class="legend">${[1, 2, 3, 4].map(k => `<span><i data-css="background:${SCALE_COLORS[k]};border-radius:50%"></i>${SCALE_LABELS[k]}</span>`).join('')}<span><i data-css="background:var(--ink);width:2px;border-radius:0"></i>District mean</span><span><i data-css="background:#fdf0ef;border:1px solid #f3cfcb"></i>Answers ${gap}+ points apart</span></div>` + s
    + `<p class="fine">Bigger dots mean more people gave that answer. "out" counts people who said the practice was outside their area.</p>`;
}

const answerPill = a => a === null ? `<span class="pill" data-css="background:${SCALE_COLORS[0]};color:${SCALE_TEXT[0]}">Outside</span>`
  : typeof a === 'number' ? `<span class="pill" data-css="background:${SCALE_COLORS[a]};color:${SCALE_TEXT[a]}">${a}</span>`
  : a === 'bad' ? '<span class="pill" title="Unreadable answer">?</span>' : '<span class="supp">–</span>';
const answerText = a => a === null ? 'Outside' : typeof a === 'number' ? String(a) : a === 'bad' ? '?' : '';
const csvCell = v => { const t = v == null ? '' : String(v); return /[",\n\r]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; };
function downloadFile(name, text, type = 'text/csv', raw = false) {
  const url = URL.createObjectURL(new Blob([(raw ? '' : '\ufeff') + text], { type: type + ';charset=utf-8' }));
  const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

/* ---------------------------------- Views ---------------------------------- */
function emptyState() {
  return `<div class="empty"><h2>Load the latest response export</h2>
  <p class="fine" data-css="max-width:620px;margin:0 auto">In the Google Sheet that collects the form responses: <b>File → Download → Comma-separated values (.csv)</b>. Then drop the file here or use <b>Load responses…</b>. The file is read inside this browser tab only: this page is blocked from making any network connection, and nothing is saved when you close it.</p>
  <div class="drop" id="drop">Drop a .csv export here<br><span class="fine">or</span><br><button class="btn primary" type="button" data-action="pick-file">Choose file…</button></div>
  <p class="fine">Received a district or ISD/RESA review pack from Ordevista? Open it in the <a href="${VIEWER_URL}">Review Pack Viewer</a>.</p></div>`;
}

function renderDash(model) {
  const el = $('view-dash');
  if (!S.all.length) { el.innerHTML = emptyState(); wireDrop(); return; }
  const k = S.settings.minCell;
  const agg = aggregate(model.districts, model.recs);
  if (model.districts.length < k) {
    el.innerHTML = mapWarning() + `<div class="card"><h2>Not enough districts to publish yet</h2><p class="sub">${model.districts.length} district${model.districts.length === 1 ? '' : 's'} so far. Statewide results appear once at least ${k} districts have responded, so no district can be identified.</p></div>`;
    return;
  }
  const b = bandOf(agg.index);
  const regionsN = new Set(model.districts.map(d => d.profile.region).filter(r => r !== 'Not reported' && r !== 'Not sure / Other')).size;
  const multiN = agg.multi.length;
  const gaps = nextSteps(agg.itemMeans);
  const bd = breakdown(model, S.dim);

  el.innerHTML = mapWarning() + `
  <div class="grid">
    <div class="card tile span-3"><div class="label">Statewide Confidence Index</div><div class="value">${fmt(agg.index)}<span data-css="font-size:16px;color:var(--muted);font-weight:400"> / 100</span></div><span class="band-chip">${esc(b.name)}</span><div class="note">Average of district scores; each district counted once</div></div>
    <div class="card tile span-3"><div class="label">Districts participating</div><div class="value">${agg.nDistricts}</div><div class="note">${agg.nDistricts >= S.settings.benchmarkMin ? 'Peer benchmarks are on' : `Peer benchmarks start at ${S.settings.benchmarkMin} districts`}</div></div>
    <div class="card tile span-3"><div class="label">Individual responses</div><div class="value">${agg.nResp}</div><div class="note">${(agg.nResp / Math.max(1, agg.nDistricts)).toFixed(1)} per district on average</div></div>
    <div class="card tile span-3"><div class="label">ISD / RESA regions represented</div><div class="value">${regionsN}</div><div class="note">${multiN} district${multiN === 1 ? '' : 's'} with more than one respondent</div></div>

    <div class="card span-7"><h2>Confidence by domain</h2><p class="sub">0–100. Read it bottom-up: each domain rests on the one below it.</p>${domainChart(agg.domains)}</div>
    <div class="card span-5"><h2>Districts by band</h2><p class="sub">No band is a failing grade.</p>${bandsChart(agg)}</div>

    <div class="card span-12"><h2>Statewide priority gaps</h2><p class="sub">The three lowest-scoring practices across participating districts, with the recommended first step for each.</p>${stepsList(gaps, agg.itemMeans)}</div>

    <div class="card span-12"><h2>How confident respondents are, question by question</h2><p class="sub">Each bar is all individual responses to that question. The mean weights each district equally. "Outside" is the share who said the question was outside their area, which is a finding in itself.</p>${questionChart(agg)}</div>

    <div class="card span-7"><h2>Results by group</h2><p class="sub">Groups with fewer than ${k} districts are combined into "Other (combined)" so no district can be identified.</p>
      <div data-css="margin-bottom:10px"><select id="dimSel" aria-label="Break results down by">${CONFIG.dims.map(d => `<option value="${d.id}" ${d.id === S.dim ? 'selected' : ''}>${esc(d.label)}</option>`).join('')}</select></div>
      ${breakdownTable(bd)}</div>
    <div class="card span-5"><h2>Biggest barrier named</h2><p class="sub">Share of individual responses.</p>${barrierChart(agg)}</div>

    <div class="card span-12"><h2>Where colleagues disagree</h2>
      ${disagreeBars(agg, k, 'statewide')}
    </div>
  </div>
  ${methodNote(agg)}`;
  $('dimSel').onchange = e => { S.dim = e.target.value; render(); };
}

function mapWarning() {
  const q = S.quality; if (!q || !q.qMissing.length) return '';
  return `<div class="banner analyst"><b>${q.qMissing.length} of 12 question columns weren't recognized (${esc(q.qMissing.join(', '))}).</b> Results below leave them out, so don't present them. Open <b>Analyst view → Data check</b> to see how each column in the file was matched.</div>`;
}

function breakdownTable(bd) {
  const unit = bd.dim.level === 'district' ? 'Districts' : 'Responses (districts)';
  return `<div class="tablewrap"><table class="data"><thead><tr><th>${esc(bd.dim.label)}</th><th class="n">${unit}</th><th>Confidence Index</th>${CONFIG.domains.map(d => `<th class="n" title="${esc(d.name)}">${d.id}</th>`).join('')}</tr></thead><tbody>
  ${bd.rows.map(r => `<tr><td>${esc(r.label)}${r.pooled ? `<div class="fine" data-tip="${esc(r.members.join(', '))}">${r.members.length} group${r.members.length === 1 ? '' : 's'} combined</div>` : ''}</td>
    <td class="n">${bd.dim.level === 'district' ? r.n : `${r.units} (${r.n})`}</td>
    <td>${r.suppressed ? '<span class="supp">Suppressed: fewer than ' + S.settings.minCell + ' districts</span>' : `<span class="minitrack"><span class="mini" data-css="width:${r.index || 0}%"></span></span>${fmt(r.index)}`}</td>
    ${CONFIG.domains.map(d => `<td class="n">${r.suppressed ? '–' : fmt(r.doms[d.id])}</td>`).join('')}</tr>`).join('')}
  </tbody></table></div><p class="fine">${CONFIG.domains.map(d => `${d.id} = ${esc(d.name)}`).join(' · ')}</p>`;
}

function methodNote(agg) {
  const latest = S.all.reduce((m, r) => (r.ts && (!m || r.ts > m) ? r.ts : m), null);
  return `<p class="fine" data-css="margin:18px 0 40px">Method: each answer of 1–4 maps to 0–100 as (answer − 1) ÷ 3 × 100. "Outside my area" is excluded from scores. When several people from one district respond, their answers are averaged per question so each district counts once. Breakdowns covering fewer than ${S.settings.minCell} districts are combined or suppressed. Respondent names, emails and free-text comments are never loaded. ${latest ? `Responses through ${latest.toLocaleDateString()}.` : ''} Cycle: ${esc(S.cycle === 'all' ? 'all cycles' : S.cycle)}.</p>`;
}

/* ---------------------------------- Report builder ---------------------------------- */
function renderReport(model) {
  const el = $('view-report');
  if (!S.all.length) { el.innerHTML = emptyState(); wireDrop(); return; }
  const k = S.settings.minCell;
  const sc = S.report.scope;
  const analystOnly = ['district', 'review', 'regionpack'];
  if (!isAnalyst() && analystOnly.includes(sc)) S.report.scope = 'state';
  const scope = S.report.scope;
  const perDistrict = scope === 'district' || scope === 'review';
  const perRegion = scope === 'region' || scope === 'regionpack';
  const regions = new Map();
  model.districts.forEach(d => { const r = d.profile.region; if (!regions.has(r)) regions.set(r, []); regions.get(r).push(d); });
  const regionOpts = [...regions.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  const regionOk = r => regions.get(r)?.length >= k && (scope === 'region' || regionKnown(r));
  if (perRegion && !regionOk(S.report.target)) S.report.target = (regionOpts.find(([r]) => regionOk(r)) || [''])[0];
  if (perDistrict && isAnalyst() && !model.districts.find(d => d.dk === S.report.target)) S.report.target = model.districts[0]?.dk || '';

  let targetCtl = '';
  if (perRegion) targetCtl = `<label>Region<select id="rTarget">${regionOpts.filter(([r]) => scope === 'region' || regionKnown(r)).map(([r, ds]) => `<option value="${esc(r)}" ${ds.length < k ? 'disabled' : ''} ${r === S.report.target ? 'selected' : ''}>${esc(r)} ${ds.length < k ? '(fewer than ' + k + ' districts)' : `(${ds.length} districts)`}</option>`).join('')}</select></label>`
    + (scope === 'regionpack' ? `<label class="check" title="District names, EEM codes and response counts. Answers are never shown by district."><input type="checkbox" id="rList" ${S.report.listDistricts ? 'checked' : ''}> List participating districts</label>` : '');
  if (perDistrict) targetCtl = `<label>District<select id="rTarget">${model.districts.map(d => `<option value="${esc(d.dk)}" ${d.dk === S.report.target ? 'selected' : ''}>${esc(d.label)}${d.code ? ' · ' + d.code : ''} (${d.n})</option>`).join('')}</select></label>`
    + (scope === 'district' ? `<label class="check"><input type="checkbox" id="rAnon" ${S.report.anonymize ? 'checked' : ''}> Shareable version (no district name or code)</label>`
      : `<label class="check" title="Unticked: counts per question only, so no one's answers can be linked across questions"><input type="checkbox" id="rPer" ${S.report.perResp ? 'checked' : ''}> One column per respondent</label>`);

  const body = scope === 'review' ? districtReview(model, model.districts.find(d => d.dk === S.report.target))
    : scope === 'regionpack' ? regionReview(model, S.report.target)
    : scope === 'district' ? districtReport(model, model.districts.find(d => d.dk === S.report.target))
    : scope === 'region' ? regionReport(model, S.report.target, regions.get(S.report.target) || [])
    : stateReport(model);

  // Email draft state survives re-renders until the pack itself changes.
  const ekey = [scope, S.report.target, S.report.perResp, S.report.listDistricts, S.cycle].join('|');
  if (body.email && (!S.report.email || S.report.email.key !== ekey)) S.report.email = { key: ekey, to: '', subject: body.email.subject, body: body.email.body, open: !!(S.report.email && S.report.email.open) };
  const em = body.email ? S.report.email : null;

  const opt = (v, label) => `<option value="${v}" ${scope === v ? 'selected' : ''}>${label}</option>`;
  el.innerHTML = `<div class="report-controls">
    <label>Report for<select id="rScope">${opt('state', 'Statewide summary')}${opt('region', 'ISD / RESA region')}${isAnalyst() ? opt('district', 'One district (analyst only)') + opt('review', 'District review pack (analyst only)') + opt('regionpack', 'ISD/RESA region review pack (analyst only)') : ''}</select></label>
    ${targetCtl}
    <button class="btn primary" id="rPrint" type="button">Print / Save as PDF</button>
    <button class="btn" id="rCopy" type="button">Copy as text</button>
    ${body.csv ? '<button class="btn" id="rCsv" type="button">Download CSV</button>' : ''}
    ${em ? `<button class="btn" id="rEmail" type="button" aria-expanded="${em.open}" aria-controls="emailPanel">Email draft…</button>` : ''}
    ${!isAnalyst() ? '<span class="fine">District and review-pack reports are available in Analyst view.</span>' : ''}
  </div>
  ${em ? `<div class="card emailpanel noprint${em.open ? '' : ' hidden'}" id="emailPanel">
    <h2>Email draft</h2>
    <p class="sub">Nothing is sent from here. Edit the message, then use one of the options below. Your edits are kept until you pick a different pack.</p>
    <div class="emailgrid">
      <label for="emTo">To</label><input id="emTo" type="email" autocomplete="off" placeholder="Contact's email (optional)" value="${esc(em.to)}">
      <label for="emSubj">Subject</label><input id="emSubj" type="text" value="${esc(em.subject)}">
      <label for="emBody">Message</label><textarea id="emBody" rows="16">${esc(em.body)}</textarea>
    </div>
    <div class="report-controls flush">
      <button class="btn primary" id="emOpen" type="button">Open in email app</button>
      <button class="btn" id="emCsv" type="button">Download CSV to attach</button>
      <button class="btn" id="emCopy" type="button">Copy message</button>
      <button class="btn" id="emEml" type="button">Download draft with CSV attached (.eml)</button>
    </div>
    <ol class="fine emailsteps">
      <li><b>Gmail or most mail apps:</b> click <b>Download CSV to attach</b>, then <b>Open in email app</b>. The message opens with the subject and text filled in. Attach the downloaded CSV before sending. (Email links can't carry attachments.)</li>
      <li><b>Outlook or Apple Mail:</b> <b>Download draft with CSV attached</b> and open the .eml file. Outlook opens it as a draft ready to send. In Apple Mail, choose <b>Message → Send Again</b> to edit and send it.</li>
    </ol>
  </div>` : ''}
  <div class="report" id="reportBody"><div class="rlogo"><img src="${LOGO_TAGLINE}" alt="Ordevista: Order for a Future with Privacy"><span>Michigan K-12 Data Governance Self-Assessment<br>${esc(S.cycle === 'all' ? 'All cycles' : S.cycle)}</span></div>${body.html}</div>`;
  $('rScope').onchange = e => { S.report.scope = e.target.value; S.report.target = ''; render(); };
  if ($('rTarget')) $('rTarget').onchange = e => { S.report.target = e.target.value; render(); };
  if ($('rAnon')) $('rAnon').onchange = e => { S.report.anonymize = e.target.checked; render(); };
  if ($('rPer')) $('rPer').onchange = e => { S.report.perResp = e.target.checked; render(); };
  if ($('rList')) $('rList').onchange = e => { S.report.listDistricts = e.target.checked; render(); };
  if ($('rCsv')) $('rCsv').onclick = () => downloadFile(body.csvName, body.csv);
  $('rPrint').onclick = () => { document.body.classList.add('printing-report'); window.print(); document.body.classList.remove('printing-report'); };
  $('rCopy').onclick = () => copyText(body.text);
  if (em) {
    $('rEmail').onclick = () => { em.open = !em.open; $('emailPanel').classList.toggle('hidden', !em.open); $('rEmail').setAttribute('aria-expanded', em.open); if (em.open) $('emTo').focus(); };
    $('emTo').oninput = e => (em.to = e.target.value);
    $('emSubj').oninput = e => (em.subject = e.target.value);
    $('emBody').oninput = e => (em.body = e.target.value);
    $('emCsv').onclick = () => downloadFile(body.csvName, body.csv);
    $('emCopy').onclick = () => copyText(`Subject: ${em.subject}\n\n${em.body}`, $('emCopy'));
    $('emOpen').onclick = () => {
      const a = document.createElement('a');
      a.href = `mailto:${encodeURIComponent(em.to.trim())}?subject=${encodeURIComponent(em.subject)}&body=${encodeURIComponent(em.body.replace(/\r?\n/g, '\r\n'))}`;
      document.body.appendChild(a); a.click(); a.remove();
    };
    $('emEml').onclick = () => downloadFile(body.csvName.replace(/\.csv$/, '') + '-email.eml', emlDraft(em.to.trim(), em.subject, em.body, body.csvName, body.csv), 'message/rfc822', true);
  }
}

function reportFoot(extra) {
  return `<div class="foot">Prepared by Ordevista · Order for a Future with Privacy · ${new Date().toLocaleDateString()}. Self-reported confidence, not a compliance audit. Aggregate results only; no individual respondent is identified. ${extra || ''}</div>`;
}
function itemTable(means, bench, extraCol) {
  return `<div class="tablewrap"><table class="data"><thead><tr><th>Practice</th><th class="n">Avg (1–4)</th>${bench ? '<th class="n">Statewide</th>' : ''}${extraCol ? `<th>${extraCol.head}</th>` : ''}</tr></thead><tbody>
  ${CONFIG.domains.map(d => `<tr><td colspan="${2 + (bench ? 1 : 0) + (extraCol ? 1 : 0)}" class="domhead" data-css="border:0;padding-top:12px">${esc(d.name)}</td></tr>` + d.items.map(n => `<tr><td>Q${n}. ${esc(CONFIG.items[n].short)}</td><td class="n">${fmt(means[n], 1)}</td>${bench ? `<td class="n">${fmt(bench[n], 1)}</td>` : ''}${extraCol ? `<td>${extraCol.cell(n)}</td>` : ''}</tr>`).join('')).join('')}
  </tbody></table></div>`;
}
function textBlock(title, idx, domains, steps, means, lines) {
  let t = `${title}\n${'='.repeat(title.length)}\nConfidence Index: ${fmt(idx)}/100 (${bandOf(idx)?.name || 'not scored'})\n\nDomain scores:\n`;
  CONFIG.domains.forEach(d => (t += `  ${d.name}: ${fmt(domains[d.id])}\n`));
  if (lines) t += '\n' + lines.join('\n') + '\n';
  t += '\nPriority next steps:\n';
  steps.forEach((n, i) => (t += `  ${i + 1}. ${CONFIG.items[n].short} (avg ${fmt(means[n], 1)}): ${CONFIG.items[n].action} [${CONFIG.items[n].cite}]\n`));
  return t + '\nSelf-reported confidence, not a compliance audit. Prepared by Ordevista.\n';
}

function stateReport(model) {
  const k = S.settings.minCell;
  if (model.districts.length < k) return { html: `<p>Statewide results appear once at least ${k} districts respond (currently ${model.districts.length}).</p>`, text: '' };
  const agg = aggregate(model.districts, model.recs);
  const steps = nextSteps(agg.itemMeans);
  const b = bandOf(agg.index);
  const html = `<div class="kicker">${esc(CONFIG.title)} · ${esc(S.cycle === 'all' ? 'All cycles' : S.cycle)}</div><h2 class="rtitle">Statewide summary</h2>
  <p class="fine">${agg.nDistricts} districts and ${agg.nResp} individual responses.</p>
  <div class="rgrid"><div><div class="tile"><div class="label">Confidence Index</div><div class="value">${fmt(agg.index)}</div><span class="band-chip">${esc(b.name)}</span><div class="note">${esc(b.hint)}</div></div></div>
  <div>${domainChart(agg.domains)}</div></div>
  <h3>Priority gaps statewide</h3>${stepsList(steps, agg.itemMeans)}
  <h3>Districts by band</h3>${bandsChart(agg)}
  <h3>By question</h3>${questionChart(agg)}
  <h3>Biggest barrier named</h3>${barrierChart(agg)}
  ${reportFoot(`Groups covering fewer than ${k} districts are combined or suppressed.`)}`;
  const text = textBlock(`${CONFIG.title}: statewide summary`, agg.index, agg.domains, steps, agg.itemMeans, [`Participation: ${agg.nDistricts} districts, ${agg.nResp} responses.`]);
  return { html, text };
}

function regionReport(model, region, ds) {
  const k = S.settings.minCell;
  if (!region || ds.length < k) return { html: `<p>No region has reached ${k} participating districts yet. Region reports are suppressed below that so no district can be identified.</p>`, text: '' };
  const dks = new Set(ds.map(d => d.dk));
  const agg = aggregate(ds, model.recs.filter(r => dks.has(r.dk)));
  const benchOn = model.districts.length >= S.settings.benchmarkMin;
  const st = aggregate(model.districts, model.recs);
  const steps = nextSteps(agg.itemMeans);
  const b = bandOf(agg.index);
  const html = `<div class="kicker">${esc(CONFIG.title)} · Regional summary</div><h2 class="rtitle">${esc(region)}</h2>
  <p class="fine">${agg.nDistricts} participating districts · ${agg.nResp} responses. District-level results are not shown.</p>
  <div class="rgrid"><div><div class="tile"><div class="label">Regional Confidence Index</div><div class="value">${fmt(agg.index)}</div><span class="band-chip">${esc(b.name)}</span>${benchOn ? `<div class="note">Statewide: ${fmt(st.index)}</div>` : ''}</div></div>
  <div>${domainChart(agg.domains, benchOn ? { bench: st.domains, selfLabel: 'This region' } : {})}${benchOn ? '' : `<p class="fine">Statewide comparison appears once ${S.settings.benchmarkMin} districts have responded.</p>`}</div></div>
  <h3>Priority gaps in the region</h3>${stepsList(steps, agg.itemMeans)}
  <h3>Districts by band</h3>${bandsChart(agg)}
  <h3>By question</h3>${questionChart(agg, 'response', benchOn ? st.itemMeans : null)}
  <h3>Where colleagues disagree</h3>${disagreeBars(agg, k, 'in the region')}${benchOn && st.multi.length >= k && agg.multi.length >= k ? `<details class="tableview"><summary>Compare with statewide</summary><div class="tablewrap"><table class="data"><thead><tr><th>Question</th><th class="n">This region</th><th class="n">Statewide</th></tr></thead><tbody>${ITEMS.map(n => `<tr><td>Q${n}. ${esc(CONFIG.items[n].short)}</td><td class="n">${pct(agg.disagree[n], agg.multi.length)}%</td><td class="n">${pct(st.disagree[n], st.multi.length)}%</td></tr>`).join('')}</tbody></table></div></details>` : ''}
  <h3>Biggest barrier named</h3>${barrierChart(agg)}
  ${reportFoot()}`;
  const dLines = agg.multi.length >= k ? ITEMS.filter(n => agg.disagree[n]).sort((a, b) => agg.disagree[b] - agg.disagree[a]).slice(0, 3).map(n => `  ${CONFIG.items[n].short}: ${pct(agg.disagree[n], agg.multi.length)}% of multi-respondent districts`) : [];
  const text = textBlock(`${region}: regional summary`, agg.index, agg.domains, steps, agg.itemMeans, [`Participation: ${agg.nDistricts} districts, ${agg.nResp} responses.`].concat(benchOn ? [`Statewide Confidence Index: ${fmt(st.index)}`] : []).concat(dLines.length ? ['Where colleagues disagree most:'].concat(dLines) : []));
  return { html, text };
}

function districtReport(model, d) {
  if (!d) return { html: '<p>No district selected.</p>', text: '' };
  const anon = S.report.anonymize;
  const benchOn = model.districts.length >= S.settings.benchmarkMin;
  const st = aggregate(model.districts, model.recs);
  const steps = nextSteps(d.itemMeans);
  const b = bandOf(d.index);
  const name = anon ? `${d.profile.enroll === 'ISD or RESA' ? 'An ISD/RESA' : 'A district'}: ${d.profile.locale.toLowerCase()}, ${d.profile.enroll === 'ISD or RESA' ? '' : d.profile.enroll + ' students'}`.replace(/,\s*$/, '') : d.label;
  const gap = S.settings.gap;
  const disagreeItems = d.n >= 2 ? ITEMS.filter(n => d.spread[n] >= gap) : [];
  const unknown = ITEMS.filter(n => d.itemMeans[n] == null);
  const wide = d.scopes.filter(s => s === 'For the district as a whole').length;
  const answerCell = n => {
    const c = d.dist[n];
    return [1, 2, 3, 4, 0].filter(k => c[k]).map(k => `<span class="pill" data-css="background:${SCALE_COLORS[k]};color:${SCALE_TEXT[k]}">${k === 0 ? 'Outside' : k}${c[k] > 1 ? ' ×' + c[k] : ''}</span>`).join(' ') + (d.spread[n] >= gap ? ' <span class="pill bad">disagree</span>' : '');
  };
  const html = `<div class="kicker">${esc(CONFIG.title)} · District profile${anon ? ' · shareable version' : ''}</div>
  <h2 class="rtitle">${esc(name)}</h2>
  <p class="fine">${anon ? '' : `${d.code ? 'EEM ' + esc(d.code) + ' · ' : ''}${esc(d.profile.region)} · `}${anon ? 'Domain scores and next steps only; individual answers removed.' : `${d.n} response${d.n === 1 ? '' : 's'} combined${d.n > 1 ? ` (${wide} district-wide, ${d.n - wide} from their own area)` : ''}. Individual answers are not attributed.`}</p>
  <div class="rgrid"><div><div class="tile"><div class="label">Confidence Index</div><div class="value">${fmt(d.index)}</div>${b ? `<span class="band-chip">${esc(b.name)}</span><div class="note">${esc(b.hint)}</div>` : ''}${benchOn ? `<div class="note">Statewide: ${fmt(st.index)}</div>` : ''}</div>
    <dl class="kv" data-css="margin-top:14px"><dt>Enrollment</dt><dd>${esc(d.profile.enroll)}</dd><dt>Locale</dt><dd>${esc(d.profile.locale)}</dd><dt>Policy service</dt><dd>${esc(d.profile.policy)}</dd><dt>Staff time</dt><dd>${esc(d.profile.staff)}</dd></dl></div>
  <div>${domainChart(d.domains, benchOn ? { bench: st.domains, selfLabel: anon ? 'This district' : d.label } : {})}${benchOn ? '' : `<p class="fine">Peer comparison unlocks once ${S.settings.benchmarkMin} districts respond (currently ${model.districts.length}).</p>`}</div></div>
  <h3>Your three priority next steps</h3>${stepsList(steps, d.itemMeans)}
  ${d.n >= 2 && !anon ? `<h3>Where your colleagues answered differently</h3>${disagreeItems.length ? `<p>On ${disagreeItems.length} practice${disagreeItems.length === 1 ? '' : 's'}, answers were ${gap} or more points apart. That usually means a practice is in place in one office but not known in another. Start the conversation there.</p>` : '<p>Your respondents broadly agreed on every practice.</p>'}${rangeChart(d)}` : ''}
  ${unknown.length ? `<h3>Questions no one could answer</h3><p>Every respondent marked these as outside their area: ${unknown.map(n => esc(CONFIG.items[n].short)).join(', ')}. Finding who owns them is a useful first step.</p>` : ''}
  ${anon ? '' : `<h3>Answers by practice</h3>${itemTable(d.itemMeans, benchOn ? st.itemMeans : null, d.n >= 2 ? { head: 'Answers given', cell: answerCell } : null)}`}
  ${reportFoot(anon ? 'District name and code removed.' : 'Prepared for this district\'s participants only. Do not share outside the district.')}`;
  const lines = anon ? [] : [`Responses combined: ${d.n}`];
  if (benchOn) lines.push(`Statewide Confidence Index: ${fmt(st.index)}`);
  if (disagreeItems.length && !anon) lines.push(`Colleagues disagreed (${gap}+ points) on: ${disagreeItems.map(n => CONFIG.items[n].short).join('; ')}`);
  if (unknown.length) lines.push(`No respondent could answer: ${unknown.map(n => CONFIG.items[n].short).join('; ')}`);
  return { html, text: textBlock(`${name}: district profile`, d.index, d.domains, steps, d.itemMeans, lines) };
}

/* ---------------------------------- District review pack ----------------------------------
   One district's own responses (unnamed, in no particular order) beside its ISD/RESA and statewide
   averages, for that district to review internally. Comparisons appear only when the region has at
   least minCell districts and the state at least benchmarkMin.

   The pack is data -> CSV -> page. The dashboard renders its preview from the CSV it is about to
   export, and the public District Review Viewer renders the same CSV with the same reviewHTML(),
   so what Ordevista previews is exactly what the district sees. */
const PACK_TAG = 'DG Self-Assessment district review pack';
const PACK_FORMAT = 1;
const regionKnown = r => !!r && r !== 'Not reported' && r !== 'Not sure / Other';
const round = (v, d) => (v == null ? null : Math.round(v * 10 ** d) / 10 ** d);

function buildPack(model, d) {
  const k = S.settings.minCell;
  const region = d.profile.region;
  const regionDs = model.districts.filter(x => x.profile.region === region);
  const regionOn = regionKnown(region) && regionDs.length >= k;
  const stateOn = model.districts.length >= S.settings.benchmarkMin;
  const rdk = new Set(regionDs.map(x => x.dk));
  const reg = regionOn ? aggregate(regionDs, model.recs.filter(r => rdk.has(r.dk))) : null;
  const st = stateOn ? aggregate(model.districts, model.recs) : null;
  // Order respondents by a hash of their answers, not by time, so column order reveals nothing.
  const h = str => { let x = 2166136261; for (let i = 0; i < str.length; i++) x = Math.imul(x ^ str.charCodeAt(i), 16777619); return x >>> 0; };
  const key = r => ITEMS.map(n => String(r.answers[n])).join('|');
  const rs = d.recs.slice().sort((a, b) => h(key(a)) - h(key(b)));
  const per = !!S.report.perResp;
  const summary = [{ key: 'Index', label: 'Confidence Index (0–100)', resp: rs.map(r => round(respIndex(r), 0)), d: round(d.index, 1), r: round(reg?.index, 1), s: round(st?.index, 1) }]
    .concat(CONFIG.domains.map(dm => ({ key: dm.id, label: `${dm.name} (0–100)`, resp: rs.map(r => round(respDomain(r, dm), 0)), d: round(d.domains[dm.id], 1), r: round(reg?.domains[dm.id], 1), s: round(st?.domains[dm.id], 1) })));
  const items = {};
  ITEMS.forEach(n => { items[n] = { answers: rs.map(r => r.answers[n]), counts: Object.assign({}, d.dist[n]), d: round(d.itemMeans[n], 2), r: round(reg?.itemMeans[n], 2), s: round(st?.itemMeans[n], 2) }; });
  return {
    meta: {
      format: PACK_FORMAT, label: d.label, code: d.code || '', region, cycle: S.cycle === 'all' ? 'All cycles' : S.cycle,
      n: d.n, perResp: per, minCell: k, benchmarkMin: S.settings.benchmarkMin, regionN: regionDs.length,
      stateN: model.districts.length, gap: S.settings.gap, prepared: new Date().toISOString().slice(0, 10),
    },
    summary: per ? summary : summary.map(x => Object.assign({}, x, { resp: [] })),
    items: per ? items : Object.fromEntries(ITEMS.map(n => [n, Object.assign({}, items[n], { answers: [] })])),
  };
}

const PACK_META = [
  ['District', 'label'], ['EEM code', 'code'], ['ISD/RESA region', 'region'], ['Cycle', 'cycle'], ['Responses', 'n'],
  ['Respondent columns', 'perResp'], ['Districts in region', 'regionN'], ['Districts statewide', 'stateN'],
  ['Regional average needs (districts)', 'minCell'], ['Statewide average needs (districts)', 'benchmarkMin'],
  ['Disagreement gap (points)', 'gap'], ['Prepared', 'prepared'],
];
const COUNT_COLS = ['Answered 1', 'Answered 2', 'Answered 3', 'Answered 4', 'Outside my area'];
const packLetters = n => Array.from({ length: n }, (_, i) => (i < 26 ? String.fromCharCode(65 + i) : 'R' + (i + 1)));

function packToCSV(p) {
  const m = p.meta, letters = packLetters(m.n);
  const rows = [[PACK_TAG, 'format ' + PACK_FORMAT]];
  PACK_META.forEach(([label, k]) => rows.push([label, k === 'perResp' ? (m.perResp ? 'One per respondent' : 'Counts only') : m[k]]));
  rows.push([]);
  const respCols = m.perResp ? letters.map(l => 'Respondent ' + l) : COUNT_COLS;
  rows.push(['Section', 'Question', 'Practice', ...respCols, 'Spread', 'District average', 'ISD/RESA average', 'Statewide average']);
  const f = v => (v == null ? '' : v);
  p.summary.forEach(x => rows.push(['Summary', x.key, x.label, ...(m.perResp ? x.resp.map(f) : COUNT_COLS.map(() => '')), '', f(x.d), f(x.r), f(x.s)]));
  CONFIG.domains.forEach(dm => dm.items.forEach(n => {
    const it = p.items[n], sp = packSpread(it.counts);
    rows.push([dm.name, 'Q' + n, CONFIG.items[n].short, ...(m.perResp ? it.answers.map(answerText) : [1, 2, 3, 4, 0].map(x => it.counts[x])), f(sp), f(it.d), f(it.r), f(it.s)]);
  }));
  return rows.map(r => r.map(csvCell).join(',')).join('\r\n');
}

function packSpread(c) { const v = [1, 2, 3, 4].filter(x => c[x]); return v.length >= 2 ? Math.max(...v) - Math.min(...v) : null; }

/* Read a review pack CSV back. Throws an Error with a plain-language message if it isn't one. */
function csvToPack(text) {
  const notPack = 'This file isn\'t a district review pack. Open the .csv file attached to the review email from Ordevista (named like DG-district-review-….csv).';
  const rows = parseCSV(String(text).replace(/^﻿/, ''), detectDelimiter(text)).map(r => r.map(c => String(c == null ? '' : c).trim()));
  if (!rows.length || rows[0][0] !== PACK_TAG) throw new Error(notPack);
  const fmtNo = +((rows[0][1] || '').match(/\d+/) || [0])[0];
  if (fmtNo > PACK_FORMAT) throw new Error('This review pack was made by a newer version of the dashboard. Please use the latest viewer.');
  const meta = { format: fmtNo };
  const hi = rows.findIndex(r => r[0] === 'Section' && r[1] === 'Question');
  if (hi < 0) throw new Error(notPack);
  rows.slice(1, hi).forEach(r => { const e = PACK_META.find(([label]) => label === r[0]); if (e) meta[e[1]] = r[1] || ''; });
  const num = v => { if (v == null || v === '') return null; const x = parseFloat(String(v).replace(',', '.')); return Number.isFinite(x) ? x : null; };
  ['n', 'regionN', 'stateN', 'minCell', 'benchmarkMin', 'gap'].forEach(k => (meta[k] = num(meta[k])));
  meta.perResp = /per respondent/i.test(meta.perResp);
  if (!meta.label || !meta.n) throw new Error(notPack);
  const head = rows[hi];
  const col = name => head.indexOf(name);
  const respIdx = head.map((h, i) => (/^Respondent /.test(h) ? i : -1)).filter(i => i >= 0);
  const countIdx = COUNT_COLS.map(col);
  const cD = col('District average'), cR = col('ISD/RESA average'), cS = col('Statewide average');
  if (cD < 0 || (meta.perResp ? respIdx.length !== meta.n : countIdx.some(i => i < 0))) throw new Error('This review pack looks incomplete or was changed after it was exported. Please ask Ordevista for a fresh copy.');
  const parseAns = v => { const s = String(v || '').trim(); if (!s) return undefined; if (/^outside/i.test(s)) return null; if (/^[1-4](\.0+)?$/.test(s)) return +s[0]; return 'bad'; };
  const summary = [], items = {};
  rows.slice(hi + 1).forEach(r => {
    if (r[0] === 'Summary') {
      const dm = CONFIG.domains.find(x => x.id === r[1]);
      if (r[1] !== 'Index' && !dm) return;
      summary.push({ key: r[1], label: r[2] || (dm ? dm.name + ' (0–100)' : 'Confidence Index (0–100)'), resp: meta.perResp ? respIdx.map(i => num(r[i])) : [], d: num(r[cD]), r: num(r[cR]), s: num(r[cS]) });
      return;
    }
    const q = (r[1] || '').match(/^Q(\d{1,2})$/); if (!q || !CONFIG.items[+q[1]]) return;
    const n = +q[1];
    const answers = meta.perResp ? respIdx.map(i => parseAns(r[i])) : [];
    let counts = { 1: 0, 2: 0, 3: 0, 4: 0, 0: 0 };
    if (meta.perResp) answers.forEach(a => { if (a === null) counts[0]++; else if (typeof a === 'number') counts[a]++; });
    else [1, 2, 3, 4, 0].forEach((x, j) => (counts[x] = num(r[countIdx[j]]) || 0));
    items[n] = { answers, counts, d: num(r[cD]), r: num(r[cR]), s: num(r[cS]) };
  });
  const missing = ITEMS.filter(n => !items[n]);
  if (missing.length) throw new Error(`This review pack is missing question${missing.length === 1 ? '' : 's'} ${missing.map(n => 'Q' + n).join(', ')}. Please ask Ordevista for a fresh copy.`);
  summary.sort((a, b) => (a.key === 'Index' ? -1 : b.key === 'Index' ? 1 : CONFIG.domains.findIndex(x => x.id === a.key) - CONFIG.domains.findIndex(x => x.id === b.key)));
  return { meta, summary, items };
}

function reviewHTML(p) {
  const m = p.meta, gap = m.gap || 2, per = m.perResp, letters = packLetters(m.n);
  const k = m.minCell, bm = m.benchmarkMin;
  const regionOn = ITEMS.some(n => p.items[n].r != null), stateOn = ITEMS.some(n => p.items[n].s != null);
  const d = { dist: {}, itemMeans: {} }; // the shape rangeChart() and nextSteps() expect
  ITEMS.forEach(n => { d.dist[n] = p.items[n].counts; d.itemMeans[n] = p.items[n].d; });
  const cmpCells = (dv, rv, sv, dec) => `<td class="n"><b>${fmt(dv, dec)}</b></td><td class="n">${regionOn ? fmt(rv, dec) : '<span class="supp">–</span>'}</td><td class="n">${stateOn ? fmt(sv, dec) : '<span class="supp">–</span>'}</td>`;
  const countCell = c => [1, 2, 3, 4, 0].filter(x => c[x]).map(x => `<span class="pill" data-css="background:${SCALE_COLORS[x]};color:${SCALE_TEXT[x]}">${x === 0 ? 'Outside' : x}${c[x] > 1 ? ' ×' + c[x] : ''}</span>`).join(' ');
  const colsN = 1 + (per ? m.n : 1) + 4;
  let table = `<div class="tablewrap"><table class="data review"><caption class="sr-only">Your respondents' answers beside district, ISD/RESA and statewide averages</caption><thead><tr><th>Practice</th>${per ? letters.map(l => `<th class="n"><span class="sr-only">Respondent </span>${l}</th>`).join('') : '<th>Answers given</th>'}<th class="n">Spread</th><th class="n">Your district</th><th class="n">ISD/RESA avg</th><th class="n">Statewide avg</th></tr></thead><tbody>`;
  p.summary.forEach(r => { table += `<tr class="sumrow"><td>${esc(r.label)}</td>${per ? r.resp.map(v => `<td class="n">${fmt(v)}</td>`).join('') : '<td></td>'}<td></td>${cmpCells(r.d, r.r, r.s, 0)}</tr>`; });
  CONFIG.domains.forEach(dm => {
    table += `<tr><td colspan="${colsN}" class="domhead" data-css="border:0;padding-top:12px">${esc(dm.name)}</td></tr>`;
    dm.items.forEach(n => {
      const it = p.items[n], sp = packSpread(it.counts), apart = sp != null && sp >= gap;
      table += `<tr${apart ? ' class="apart"' : ''}><td>Q${n}. ${esc(CONFIG.items[n].short)}</td>${per ? it.answers.map(a => `<td class="n">${answerPill(a)}</td>`).join('') : `<td>${countCell(it.counts)}</td>`}<td class="n">${sp == null ? '–' : sp}${apart ? ' <span class="pill bad">apart</span>' : ''}</td>${cmpCells(it.d, it.r, it.s, 2)}</tr>`;
    });
  });
  table += '</tbody></table></div>';

  const why = [];
  if (!regionOn) why.push(regionKnown(m.region) ? `ISD/RESA averages appear once ${k} districts in ${esc(m.region)} have responded (currently ${m.regionN}).` : 'No ISD/RESA region was reported for this district, so there is no regional average.');
  if (!stateOn) why.push(`Statewide averages appear once ${bm} districts have responded (currently ${m.stateN}).`);
  const pd = /^\d{4}-\d{2}-\d{2}$/.test(m.prepared || '') ? new Date(m.prepared + 'T12:00:00') : null;
  const prepared = pd ? pd.toLocaleDateString() : (m.prepared || ''); // Excel may have reformatted the date

  const html = `<div class="kicker">${esc(CONFIG.title)} · District review</div>
  <h2 class="rtitle" tabindex="-1">${esc(m.label)}</h2>
  <p class="fine">${m.code ? 'EEM ' + esc(m.code) + ' · ' : ''}${esc(m.region)} · ${m.n} response${m.n === 1 ? '' : 's'} · ${esc(m.cycle)}</p>
  <div class="banner info">Prepared for this district's own review. ${per ? `Each lettered column is one of your ${m.n} respondents. Names, roles and emails are not included, and the columns are in no particular order.` : 'Answers are shown as counts per question, without linking any one person\'s answers together.'} Averages weight each district equally. Answers are 1 (not confident) to 4 (fully confident). Rows marked "apart" are questions where your respondents were ${gap}+ points apart.</div>
  ${why.length ? `<p class="fine">${why.join(' ')}</p>` : ''}
  <h3>Your answers beside the averages</h3>${table}
  ${m.n >= 2 ? `<h3>How far apart your answers were</h3>${rangeChart(d)}` : ''}
  <h3>Your three priority next steps</h3>${stepsList(nextSteps(d.itemMeans), d.itemMeans)}
  <div class="foot">Prepared by Ordevista · Order for a Future with Privacy${prepared ? ' · ' + esc(prepared) : ''}. Self-reported confidence, not a compliance audit. Respondents are not named; regional and statewide figures are averages of at least ${k} and ${bm} districts respectively. Prepared for this district's participants only. Do not share outside the district.</div>`;

  let t = `${m.label}: district review\n${'='.repeat(m.label.length + 17)}\n${m.n} response${m.n === 1 ? '' : 's'}. ${per ? 'Respondents ' + letters.join(', ') + ' are unnamed and in no particular order.' : ''}\n`;
  t += `Columns: ${per ? 'your answers | ' : ''}district avg | ${regionOn ? 'ISD/RESA avg' : 'ISD/RESA avg (not yet available)'} | ${stateOn ? 'statewide avg' : 'statewide avg (not yet available)'}\n\n`;
  p.summary.forEach(r => (t += `${r.label}: ${per ? r.resp.map(v => fmt(v)).join(' ') + ' | ' : ''}${fmt(r.d)} | ${regionOn ? fmt(r.r) : '–'} | ${stateOn ? fmt(r.s) : '–'}\n`));
  CONFIG.domains.forEach(dm => { t += `\n${dm.name}\n`; dm.items.forEach(n => {
    const it = p.items[n], sp = packSpread(it.counts);
    t += `  Q${n}. ${CONFIG.items[n].short}: ${per ? it.answers.map(a => answerText(a) || '-').join(' ') : [1, 2, 3, 4, 0].filter(x => it.counts[x]).map(x => `${x === 0 ? 'Outside' : x}×${it.counts[x]}`).join(' ')} | ${fmt(it.d, 2)} | ${regionOn ? fmt(it.r, 2) : '–'} | ${stateOn ? fmt(it.s, 2) : '–'}${sp != null && sp >= gap ? '  (answers ' + sp + ' points apart)' : ''}\n`;
  }); });
  if (why.length) t += '\n' + why.join(' ').replace(/&amp;/g, '&') + '\n';
  t += '\nSelf-reported confidence, not a compliance audit. Prepared by Ordevista for this district\'s participants only.\n';
  return { html, text: t };
}

function districtReview(model, d) {
  if (!d) return { html: '<p>No district selected.</p>', text: '' };
  const csv = packToCSV(buildPack(model, d));
  const back = csvToPack(csv);
  const view = reviewHTML(back); // preview from the exported file itself
  const slug = (d.code || d.label).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40);
  const csvName = `DG-district-review-${slug}-${(S.cycle === 'all' ? 'all' : S.cycle).replace(/[^0-9A-Za-z]+/g, '-')}.csv`;
  const regionOn = ITEMS.some(n => back.items[n].r != null), stateOn = ITEMS.some(n => back.items[n].s != null);
  return Object.assign(view, { csv, csvName, email: districtEmail(back.meta, csvName, regionOn, stateOn) });
}

/* ---------------------------------- ISD/RESA region review pack ----------------------------------
   Every response from one region's participating districts, with district names and codes, respondent
   names, roles and emails removed, in no particular order, beside region and statewide averages.
   Only built when the region has at least minCell districts. Same data -> CSV -> page path as the
   district pack, so the viewer shows exactly what the dashboard previews. */
const REGION_TAG = 'DG Self-Assessment region review pack';
const REGION_META = [
  ['ISD/RESA region', 'region'], ['Cycle', 'cycle'], ['Participating districts', 'districts'], ['Responses', 'n'],
  ['Districts with 2+ respondents', 'multi'], ['Districts statewide', 'stateN'], ['Minimum districts per group', 'minCell'],
  ['Statewide average needs (districts)', 'benchmarkMin'], ['Disagreement gap (points)', 'gap'], ['Prepared', 'prepared'],
];
const ansHash = str => { let x = 2166136261; for (let i = 0; i < str.length; i++) x = Math.imul(x ^ str.charCodeAt(i), 16777619); return x >>> 0; };

function buildRegionPack(model, region) {
  const k = S.settings.minCell;
  const ds = model.districts.filter(x => x.profile.region === region);
  if (!regionKnown(region) || ds.length < k) return null;
  const dks = new Set(ds.map(d => d.dk));
  const recs = model.recs.filter(r => dks.has(r.dk));
  const agg = aggregate(ds, recs);
  const stateOn = model.districts.length >= S.settings.benchmarkMin;
  const st = stateOn ? aggregate(model.districts, model.recs) : null;
  const multiOn = agg.multi.length >= k;
  const key = r => ITEMS.map(n => String(r.answers[n])).join('|');
  const rs = recs.slice().sort((a, b) => ansHash(key(a)) - ansHash(key(b)));
  return {
    kind: 'region',
    meta: { format: PACK_FORMAT, region, cycle: S.cycle === 'all' ? 'All cycles' : S.cycle, districts: ds.length, n: recs.length,
      multi: agg.multi.length, stateN: model.districts.length, minCell: k, benchmarkMin: S.settings.benchmarkMin, gap: S.settings.gap,
      prepared: new Date().toISOString().slice(0, 10) },
    summary: [{ key: 'Index', label: 'Confidence Index (0–100)', r: round(agg.index, 1), s: round(st?.index, 1) }]
      .concat(CONFIG.domains.map(dm => ({ key: dm.id, label: `${dm.name} (0–100)`, r: round(agg.domains[dm.id], 1), s: round(st?.domains[dm.id], 1) }))),
    items: Object.fromEntries(ITEMS.map(n => [n, { counts: Object.assign({}, agg.dist[n]), r: round(agg.itemMeans[n], 2), s: round(st?.itemMeans[n], 2), apart: multiOn ? agg.disagree[n] : null }])),
    responses: rs.map(r => ITEMS.map(n => r.answers[n])),
    // Who took part (names and counts only, never answers), so the ISD can see its region's coverage.
    participation: S.report.listDistricts ? ds.map(d => ({ name: d.label, code: d.code || '', n: d.n })).sort((a, b) => a.name.localeCompare(b.name)) : null,
  };
}

function regionPackToCSV(p) {
  const m = p.meta, f = v => (v == null ? '' : v);
  const rows = [[REGION_TAG, 'format ' + PACK_FORMAT]];
  REGION_META.forEach(([label, k]) => rows.push([label, m[k]]));
  rows.push([]);
  rows.push(['Section', 'Question', 'Practice', ...COUNT_COLS, 'Region average', 'Statewide average', 'Districts with answers apart']);
  p.summary.forEach(x => rows.push(['Summary', x.key, x.label, ...COUNT_COLS.map(() => ''), f(x.r), f(x.s), '']));
  CONFIG.domains.forEach(dm => dm.items.forEach(n => {
    const it = p.items[n];
    rows.push([dm.name, 'Q' + n, CONFIG.items[n].short, ...[1, 2, 3, 4, 0].map(x => it.counts[x]), f(it.r), f(it.s), f(it.apart)]);
  }));
  if (p.participation) {
    rows.push([]);
    rows.push(['District', 'EEM code', 'Responses']);
    p.participation.forEach(x => rows.push([x.name, x.code, x.n]));
  }
  rows.push([]);
  rows.push(['Response', ...ITEMS.map(n => 'Q' + n)]);
  p.responses.forEach((a, i) => rows.push(['R' + (i + 1), ...a.map(answerText)]));
  return rows.map(r => r.map(csvCell).join(',')).join('\r\n');
}

function csvToRegionPack(rows) {
  const bad = 'This region review pack looks incomplete or was changed after it was exported. Please ask Ordevista for a fresh copy.';
  const num = v => { if (v == null || v === '') return null; const x = parseFloat(String(v).replace(',', '.')); return Number.isFinite(x) ? x : null; };
  const meta = { format: +((rows[0][1] || '').match(/\d+/) || [0])[0] };
  const hi = rows.findIndex(r => r[0] === 'Section' && r[1] === 'Question');
  const ri = rows.findIndex(r => r[0] === 'Response' && r[1] === 'Q1');
  const pi = rows.findIndex(r => r[0] === 'District' && r[1] === 'EEM code' && r[2] === 'Responses');
  if (hi < 0 || ri < 0) throw new Error(bad);
  const itemsEnd = pi > hi && pi < ri ? pi : ri;
  const participation = pi > hi && pi < ri ? rows.slice(pi + 1, ri).filter(r => r[0]).map(r => ({ name: r[0], code: r[1] || '', n: num(r[2]) || 0 })) : null;
  rows.slice(1, hi).forEach(r => { const e = REGION_META.find(([label]) => label === r[0]); if (e) meta[e[1]] = r[1] || ''; });
  ['districts', 'n', 'multi', 'stateN', 'minCell', 'benchmarkMin', 'gap'].forEach(k => (meta[k] = num(meta[k])));
  const head = rows[hi], col = name => head.indexOf(name);
  const cc = COUNT_COLS.map(col), cR = col('Region average'), cS = col('Statewide average'), cA = col('Districts with answers apart');
  if (cc.some(i => i < 0) || cR < 0) throw new Error(bad);
  const summary = [], items = {};
  rows.slice(hi + 1, itemsEnd).forEach(r => {
    if (r[0] === 'Summary') { if (r[1] === 'Index' || CONFIG.domains.some(x => x.id === r[1])) summary.push({ key: r[1], label: r[2], r: num(r[cR]), s: num(r[cS]) }); return; }
    const q = (r[1] || '').match(/^Q(\d{1,2})$/); if (!q || !CONFIG.items[+q[1]]) return;
    const counts = {}; [1, 2, 3, 4, 0].forEach((x, j) => (counts[x] = num(r[cc[j]]) || 0));
    items[+q[1]] = { counts, r: num(r[cR]), s: num(r[cS]), apart: cA >= 0 ? num(r[cA]) : null };
  });
  const parseAns = v => { const s = String(v || '').trim(); if (!s) return undefined; if (/^outside/i.test(s)) return null; if (/^[1-4](\.0+)?$/.test(s)) return +s[0]; return 'bad'; };
  const qcols = ITEMS.map(n => rows[ri].indexOf('Q' + n));
  const responses = rows.slice(ri + 1).filter(r => /^R\d+$/.test(r[0])).map(r => qcols.map(i => parseAns(r[i])));
  if (ITEMS.some(n => !items[n]) || !responses.length || (meta.n && responses.length !== meta.n)) throw new Error(bad);
  summary.sort((a, b) => (a.key === 'Index' ? -1 : b.key === 'Index' ? 1 : CONFIG.domains.findIndex(x => x.id === a.key) - CONFIG.domains.findIndex(x => x.id === b.key)));
  return { kind: 'region', meta, summary, items, responses, participation };
}

/* Read either kind of review pack. Throws an Error with a plain-language message. */
function readPack(text) {
  const rows = parseCSV(String(text).replace(/^﻿/, ''), detectDelimiter(text)).map(r => r.map(c => String(c == null ? '' : c).trim()));
  if (rows.length && rows[0][0] === REGION_TAG) {
    if (+((rows[0][1] || '').match(/\d+/) || [0])[0] > PACK_FORMAT) throw new Error('This review pack was made by a newer version of the dashboard. Please use the latest viewer.');
    return csvToRegionPack(rows);
  }
  return Object.assign(csvToPack(text), { kind: 'district' });
}

function regionReviewHTML(p) {
  const m = p.meta, k = m.minCell, bm = m.benchmarkMin, gap = m.gap || 2;
  const stateOn = ITEMS.some(n => p.items[n].s != null);
  const multiOn = ITEMS.some(n => p.items[n].apart != null);
  const sum = Object.fromEntries(p.summary.map(x => [x.key, x]));
  const domains = Object.fromEntries(CONFIG.domains.map(d => [d.id, sum[d.id]?.r ?? null]));
  const sDomains = Object.fromEntries(CONFIG.domains.map(d => [d.id, sum[d.id]?.s ?? null]));
  const agg = { dist: {}, itemMeans: {}, outsideRate: {} };
  ITEMS.forEach(n => { const c = p.items[n].counts, t = c[0] + c[1] + c[2] + c[3] + c[4]; agg.dist[n] = c; agg.itemMeans[n] = p.items[n].r; agg.outsideRate[n] = t ? c[0] / t : 0; });
  const sMeans = Object.fromEntries(ITEMS.map(n => [n, p.items[n].s]));
  const steps = nextSteps(agg.itemMeans);
  const idx = sum.Index?.r ?? null, b = bandOf(idx);
  const respIdx = a => toIndex(mean(a.map(v => (typeof v === 'number' ? v : null))));
  const respTable = `<div class="tablewrap"><table class="data review"><caption class="sr-only">Every response in the region, in no particular order</caption><thead><tr><th>Response</th>${ITEMS.map(n => `<th class="n" title="${esc(CONFIG.items[n].short)}">Q${n}</th>`).join('')}<th class="n">Index</th></tr></thead><tbody>
    ${p.responses.map((a, i) => `<tr><td>R${i + 1}</td>${a.map(v => `<td class="n">${answerPill(v)}</td>`).join('')}<td class="n">${fmt(respIdx(a))}</td></tr>`).join('')}</tbody></table></div>
    <p class="fine">${ITEMS.map(n => `Q${n} ${esc(CONFIG.items[n].short)}`).join(' · ')}</p>`;
  const html = `<div class="kicker">${esc(CONFIG.title)} · ISD/RESA region review</div>
  <h2 class="rtitle" tabindex="-1">${esc(m.region)}</h2>
  <p class="fine">${m.districts} participating districts · ${m.n} responses · ${esc(m.cycle)}</p>
  <div class="banner info">Prepared for this ISD/RESA's own review. It lists every response from the ${m.districts} participating districts in the region, in no particular order. Responses carry no district name or code, and no respondent name, role or email, so they can't be traced to a district. Averages count each district once, however many people responded. Answers are 1 (not confident) to 4 (fully confident).</div>
  ${stateOn ? '' : `<p class="fine">Statewide averages appear once ${bm} districts have responded (currently ${m.stateN}).</p>`}
  <div class="rgrid"><div><div class="tile"><div class="label">Regional Confidence Index</div><div class="value">${fmt(idx)}</div>${b ? `<span class="band-chip">${esc(b.name)}</span>` : ''}${stateOn ? `<div class="note">Statewide: ${fmt(sum.Index?.s)}</div>` : ''}</div></div>
  <div>${domainChart(domains, stateOn ? { bench: sDomains, selfLabel: 'This region' } : {})}</div></div>
  <h3>Priority gaps in the region</h3>${stepsList(steps, agg.itemMeans)}
  <h3>By question</h3>${questionChart(agg, 'response', stateOn ? sMeans : null)}
  <h3>Where colleagues disagree</h3>${multiOn ? `<p class="fine">Of the ${m.multi} districts in the region with more than one respondent, the share where answers to a question were ${gap}+ points apart.</p>${hbars(ITEMS.map(n => ({ label: `Q${n}. ${CONFIG.items[n].short}`, value: p.items[n].apart, text: `${pct(p.items[n].apart, m.multi)}%`, tip: `${p.items[n].apart} of ${m.multi} multi-respondent districts` })), { max: m.multi })}` : `<p class="fine">Shown once at least ${k} districts in the region have more than one respondent (currently ${m.multi}).</p>`}
  ${p.participation ? `<h3>Participating districts</h3><p class="fine">Who took part and how many people responded. Answers are not shown by district.</p><div class="tablewrap"><table class="data"><caption class="sr-only">Participating districts and number of responses</caption><thead><tr><th>District</th><th>EEM code</th><th class="n">Responses</th></tr></thead><tbody>${p.participation.map(x => `<tr><td>${esc(x.name)}</td><td>${esc(x.code || '—')}</td><td class="n">${x.n}</td></tr>`).join('')}<tr class="sumrow"><td><b>Total</b></td><td></td><td class="n"><b>${p.participation.reduce((a, x) => a + x.n, 0)}</b></td></tr></tbody></table></div>` : ''}
  <h3>Every response</h3><p class="fine">One row per response. Rows are in no particular order and can't be traced to a district.</p>${respTable}
  <div class="foot">Prepared by Ordevista · Order for a Future with Privacy. Self-reported confidence, not a compliance audit. District and respondent details are removed; regions need at least ${k} participating districts before this pack is produced. Prepared for this ISD/RESA's own planning. Please don't try to identify individual districts, and don't share outside the ISD/RESA.</div>`;
  let t = `${m.region}: ISD/RESA region review\n${'='.repeat(m.region.length + 26)}\n${m.districts} participating districts, ${m.n} responses (unnamed, in no particular order).\n`;
  t += `Columns: region avg | ${stateOn ? 'statewide avg' : 'statewide avg (not yet available)'}\n\n`;
  p.summary.forEach(x => (t += `${x.label}: ${fmt(x.r)} | ${stateOn ? fmt(x.s) : '–'}\n`));
  CONFIG.domains.forEach(dm => { t += `\n${dm.name}\n`; dm.items.forEach(n => { const it = p.items[n]; t += `  Q${n}. ${CONFIG.items[n].short}: ${fmt(it.r, 2)} | ${stateOn ? fmt(it.s, 2) : '–'} · answers ${[1, 2, 3, 4, 0].filter(x => it.counts[x]).map(x => `${x === 0 ? 'Outside' : x}×${it.counts[x]}`).join(' ')}\n`; }); });
  if (p.participation) { t += '\nParticipating districts (responses):\n'; p.participation.forEach(x => (t += `  ${x.name}${x.code ? ' (' + x.code + ')' : ''}: ${x.n}\n`)); }
  t += '\nPriority gaps:\n'; steps.forEach((n, i) => (t += `  ${i + 1}. ${CONFIG.items[n].short} (avg ${fmt(agg.itemMeans[n], 1)}): ${CONFIG.items[n].action}\n`));
  t += '\nSelf-reported confidence, not a compliance audit. Prepared by Ordevista for this ISD/RESA\'s own planning.\n';
  return { html, text: t };
}

function regionReview(model, region) {
  const pack = buildRegionPack(model, region);
  if (!pack) return { html: `<p>Region review packs need at least ${S.settings.minCell} participating districts in the region.</p>`, text: '' };
  const csv = regionPackToCSV(pack);
  const back = readPack(csv);
  const view = regionReviewHTML(back);
  const slug = region.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40);
  const csvName = `DG-region-review-${slug}-${(S.cycle === 'all' ? 'all' : S.cycle).replace(/[^0-9A-Za-z]+/g, '-')}.csv`;
  return Object.assign(view, { csv, csvName, email: regionEmail(Object.assign({}, back.meta, { listed: !!back.participation }), csvName) });
}

/* ---------------------------------- Email drafts ----------------------------------
   The dashboard never sends anything. These build the message text; "Open in email app" hands it to
   the computer's mail program (mailto can't attach files), and the .eml download carries the CSV as an
   attachment for mail apps that open .eml files as drafts (Outlook, Apple Mail). */
const VIEWER_URL = 'https://k12.ordevista.com/dg-review/';
const SIGNATURE = 'Kurt Rheaume\nOrdevista · Order for a Future with Privacy';
const VIEW_STEPS = csvName => `To view it:\n1. Save the attached file (${csvName}) to your computer.\n2. Go to ${VIEWER_URL} in Chrome, Edge, Safari or Firefox.\n3. Click "Open review pack…" and choose the file.\n\nThe file is read only inside your browser. The page can't upload it anywhere and sets no cookies. From there you can print the review or save it as a PDF.`;

function districtEmail(m, csvName, regionOn, stateOn) {
  const avg = regionOn && stateOn ? 'beside your ISD/RESA and statewide averages' : regionOn ? 'beside your ISD/RESA average' : stateOn ? 'beside the statewide average' : 'with your district averages';
  const notes = [];
  if (!regionOn) notes.push(regionKnown(m.region) ? `Your ISD/RESA average will be added once ${m.minCell} districts in ${m.region} have responded (currently ${m.regionN}).` : 'No ISD/RESA region was reported, so there is no regional average.');
  if (!stateOn) notes.push(`Statewide averages will be added once ${m.benchmarkMin} districts have responded (currently ${m.stateN}).`);
  const body = `Hello,\n\nThank you for taking part in the Michigan K-12 Data Governance Self-Assessment. Attached is ${m.label}'s review pack: the answers from your ${m.n} respondent${m.n === 1 ? '' : 's'}, ${avg}, so your team can see where you agree, where you don't, and where to start.\n\n${VIEW_STEPS(csvName)}\n\n${m.perResp ? 'Each lettered column is one respondent. Names, roles and emails aren\'t included, and the columns are in no particular order.' : 'Answers are shown as counts per question, so no one\'s answers are linked together.'} Please keep the results within your district.${notes.length ? '\n\n' + notes.join(' ') : ''}\n\nQuestions? Just reply to this email.\n\n${SIGNATURE}`;
  return { subject: `Your Data Governance Self-Assessment review: ${m.label}`, body };
}
function regionEmail(m, csvName) {
  const stateNote = m.stateN >= m.benchmarkMin ? 'beside statewide averages' : `(statewide averages will be added once ${m.benchmarkMin} districts have responded)`;
  const body = `Hello,\n\nAttached is the Michigan K-12 Data Governance Self-Assessment review pack for ${m.region}: all ${m.n} responses from the ${m.districts} participating districts in your region, ${stateNote}, to help plan regional support.${m.listed ? ' It also lists which districts took part and how many people from each responded.' : ''}\n\n${VIEW_STEPS(csvName)}\n\nDistrict names and codes, and respondents' names, roles and emails, are removed from the responses, which are in no particular order. Please don't try to identify individual districts, and keep the pack within your ISD/RESA.\n\nQuestions? Just reply to this email.\n\n${SIGNATURE}`;
  return { subject: `Data Governance Self-Assessment region review: ${m.region}`, body };
}

/* A draft .eml with the CSV attached. X-Unsent makes Outlook open it as an editable draft. */
function emlDraft(to, subject, body, fileName, csv) {
  const b64 = str => { const bytes = new TextEncoder().encode(str); let bin = ''; bytes.forEach(x => (bin += String.fromCharCode(x))); return btoa(bin).replace(/.{1,76}/g, '$&\r\n').trim(); };
  const enc = str => (/^[\x20-\x7e]*$/.test(str) ? str : `=?UTF-8?B?${b64(str).replace(/\r\n/g, '')}?=`);
  const bd = 'dgsa-' + Date.now().toString(36);
  return [`To: ${to || ''}`, `Subject: ${enc(subject)}`, 'X-Unsent: 1', 'MIME-Version: 1.0', `Content-Type: multipart/mixed; boundary="${bd}"`, '',
    `--${bd}`, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(body.replace(/\r?\n/g, '\r\n')),
    `--${bd}`, `Content-Type: text/csv; charset=UTF-8; name="${fileName}"`, `Content-Disposition: attachment; filename="${fileName}"`, 'Content-Transfer-Encoding: base64', '', b64('﻿' + csv),
    `--${bd}--`, ''].join('\r\n');
}

/* ---------------------------------- Data check (analyst) ---------------------------------- */
function renderCheck(model) {
  const el = $('view-check');
  if (!isAnalyst()) { el.innerHTML = ''; return; }
  if (!S.all.length) { el.innerHTML = emptyState(); wireDrop(); return; }
  const q = S.quality;
  const cycles = {}; S.all.forEach(r => (cycles[r.cycle] = (cycles[r.cycle] || 0) + 1));
  const confl = new Map(); model.conflicts.forEach(c => { if (!confl.has(c.dk)) confl.set(c.dk, []); confl.get(c.dk).push(c.field); });
  el.innerHTML = `<div class="grid">
  <div class="card span-5"><h2>File</h2><dl class="kv">
    <dt>File</dt><dd>${esc(S.fileName)}</dd><dt>Loaded</dt><dd>${S.loadedAt.toLocaleString()}</dd>
    <dt>Rows read</dt><dd>${q.rowsRead}</dd><dt>Resubmissions removed</dt><dd>${q.dupes} <span class="fine">(same email + district: latest kept)</span></dd>
    <dt>Rows without a district</dt><dd>${q.noDistrict}</dd><dt>Responses used</dt><dd>${S.all.length}</dd>
    <dt>Cycles</dt><dd>${Object.entries(cycles).map(([c, n]) => `${esc(c)}: ${n}`).join(' · ')}</dd>
    <dt>Missing columns</dt><dd>${q.missingCols.length ? `<span class="pill bad">${esc(q.missingCols.join(', '))}</span>` : '<span class="pill good">none</span>'}</dd>
    <dt>Unreadable answers</dt><dd>${q.badAnswers}</dd><dt>Blank answers</dt><dd>${q.blankAnswers}</dd>
    <dt>Free-text comments</dt><dd>${q.freeTextCount} <span class="fine">(not loaded; read them in the Sheet)</span></dd>
  </dl></div>
  <div class="card span-7"><h2>Entity codes to match by hand</h2><p class="sub">Respondents who typed NOT FOUND or no code. They are grouped by district name for now. Add the code in the Sheet to merge them properly.</p>
    ${q.notFound.length ? `<table class="data"><thead><tr><th>Code entered</th><th>Name entered</th></tr></thead><tbody>${q.notFound.map(x => `<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td></tr>`).join('')}</tbody></table>` : '<p class="fine">None.</p>'}</div>
  ${columnMapCard(q)}
  <div class="card span-12"><h2>Districts (${model.districts.length})</h2><p class="sub">Analyst only. Profile conflicts mean respondents from one district gave different profile answers; the most common answer is used.</p>
    <div class="tablewrap"><table class="data"><thead><tr><th>District</th><th>EEM</th><th>Region</th><th class="n">Responses</th><th class="n">Index</th><th>Band</th><th class="n">Disagreements</th><th>Profile conflicts</th><th>Follow-up requested</th></tr></thead><tbody>
    ${model.districts.map(d => `<tr><td>${esc(d.label)}</td><td>${esc(d.code || '—')}</td><td>${esc(d.profile.region)}</td><td class="n">${d.n}</td><td class="n">${fmt(d.index)}</td><td>${esc(bandOf(d.index)?.name || 'Not scored')}</td><td class="n">${d.n >= 2 ? ITEMS.filter(n => d.spread[n] >= S.settings.gap).length : '–'}</td><td>${esc((confl.get(d.dk) || []).join(', '))}</td><td>${d.n >= 2 ? d.recs.filter(r => /^yes/i.test(r.followup)).length + ' of ' + d.n : '–'}</td></tr>`).join('')}
    </tbody></table></div></div>
  </div>`;
}

function columnMapCard(q) {
  const m = q.map; if (!m) return '';
  const field = {};
  Object.entries(m.col).forEach(([k, i]) => (field[i] = k));
  Object.entries(m.qcol).forEach(([n, i]) => (field[i] = `Q${n} · ${CONFIG.items[n].short} (by ${m.how[n]})`));
  const ignored = new Set(['name', 'email', 'freetext', 'contact']);
  const headerList = m.header.map((h, i) => `${i + 1}\t${h}`).join('\n');
  window.__headerList = headerList;
  return `<div class="card span-12"><h2>Column mapping</h2>
  <p class="sub">Header found on row ${m.headerRow + 1} of the file · delimiter "${esc(q.delim)}". ${q.qMissing.length ? `<span class="pill bad">Missing: ${esc(q.qMissing.join(', '))}</span>` : '<span class="pill good">All 12 questions matched</span>'} ${m.note ? esc(m.note) : ''}</p>
  <p class="fine">Header labels are the form's question titles, not anyone's answers. <button class="btn" type="button" data-action="copy-headers">Copy header labels</button></p>
  <div class="tablewrap"><table class="data"><thead><tr><th class="n">#</th><th>Column header in file</th><th>Used as</th></tr></thead><tbody>
  ${m.header.map((h, i) => `<tr><td class="n">${i + 1}</td><td>${esc(h.length > 110 ? h.slice(0, 110) + '…' : h)}</td><td>${field[i] ? (ignored.has(field[i]) ? `<span class="fine">${esc(field[i])}: not loaded</span>` : esc(field[i])) : '<span class="supp">not used</span>'}</td></tr>`).join('')}
  </tbody></table></div></div>`;
}


/* ---------------------------------- District Review Viewer ----------------------------------
   Public page. Reads one review pack CSV in the browser and renders it with the dashboard's own
   reviewHTML(). No inline styles or handlers: the site's CSP (style-src 'self') blocks them, so
   style attributes in rendered markup are applied through the CSSOM instead. */
(function () {
  let current = null;
  const mount = (el, html) => { el.innerHTML = html; applyCss(el); el.querySelectorAll('thead th').forEach(th => th.setAttribute('scope', 'col')); };
  const showErr = msg => { $('err').textContent = msg; $('status').textContent = 'No file open.'; };

  function show(pack) {
    S.settings.gap = pack.meta.gap || 2;
    current = pack.kind === 'region' ? regionReviewHTML(pack) : reviewHTML(pack);
    const name = pack.kind === 'region' ? pack.meta.region : pack.meta.label;
    mount($('reportBody'), `<div class="rlogo"><img src="${LOGO_TAGLINE}" alt="Ordevista: Order for a Future with Privacy"><span>Michigan K-12 Data Governance Self-Assessment<br>${esc(pack.meta.cycle || '')}</span></div>` + current.html);
    document.title = `${name} · Review Pack Viewer · Ordevista`;
    $('err').textContent = '';
    $('intro').classList.add('hidden');
    $('out').classList.remove('hidden');
    $('status').innerHTML = `Showing <b>${esc(name)}</b> · ${pack.meta.n} response${pack.meta.n === 1 ? '' : 's'}`;
    const h = document.querySelector('#reportBody .rtitle'); if (h) h.focus();
  }

  function openFile(file) {
    if (!file) return;
    if (!/\.(csv|txt)$/i.test(file.name)) { showErr('Please choose the .csv review pack file (named like DG-district-review-….csv or DG-region-review-….csv).'); return; }
    const fr = new FileReader();
    fr.onload = () => { try { show(readPack(String(fr.result))); } catch (e) { showErr(e.message); } };
    fr.onerror = () => showErr('That file couldn\'t be read. Try saving it to your computer first, then open it here.');
    fr.readAsText(file);
  }

  function closeFile() {
    current = null;
    $('reportBody').innerHTML = '';
    $('out').classList.add('hidden');
    $('intro').classList.remove('hidden');
    $('status').textContent = 'File closed. Nothing was saved.';
    document.title = 'Review Pack Viewer · Ordevista';
    $('chooseBtn').focus();
  }

  function copy() {
    if (!current) return;
    const b = $('copyBtn');
    const done = () => { $('live').textContent = ''; setTimeout(() => ($('live').textContent = 'Copied to clipboard'), 50); const o = b.textContent; b.textContent = 'Copied'; setTimeout(() => (b.textContent = o), 1400); };
    const fallback = () => { const ta = document.createElement('textarea'); ta.value = current.text; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); done(); } catch (e) { /* nothing */ } ta.remove(); };
    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(current.text).then(done, fallback); else fallback();
  }

  $('openBtn').addEventListener('click', () => $('fileIn').click());
  $('chooseBtn').addEventListener('click', () => $('fileIn').click());
  $('fileIn').addEventListener('change', e => { openFile(e.target.files[0]); e.target.value = ''; });
  $('printBtn').addEventListener('click', () => window.print());
  $('copyBtn').addEventListener('click', copy);
  $('closeBtn').addEventListener('click', closeFile);
  const drop = $('drop');
  drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('over'); });
  drop.addEventListener('dragleave', () => drop.classList.remove('over'));
  document.addEventListener('dragover', e => e.preventDefault());
  document.addEventListener('drop', e => { e.preventDefault(); drop.classList.remove('over'); if (e.dataTransfer.files[0]) openFile(e.dataTransfer.files[0]); });

  const tip = $('tip');
  document.addEventListener('mousemove', e => {
    const t = e.target.closest && e.target.closest('[data-tip]');
    if (!t || !t.getAttribute('data-tip')) { tip.style.display = 'none'; return; }
    tip.textContent = t.getAttribute('data-tip'); tip.style.display = 'block';
    tip.style.left = Math.min(e.clientX + 14, window.innerWidth - tip.offsetWidth - 8) + 'px'; tip.style.top = (e.clientY + 16) + 'px';
  });
})();
